values ('9e17060e-63ca-6dcc-abc1-8fa9edb280e7', 'hq', 'Frequency', 'business', 'active', (select entity_id from spaces where type = 'root' order by created_at limit 1), 'dawn', true, 'network', 'collective', true, true, '{}'::jsonb, '78d47bae-c4c8-4d1c-80a0-ac69aaf98ef8', 'Frequency', '#1AA7C0', 'Gather like it matters.', 'This is the Frequency team''s own Space: the home base for everyone building Frequency. Find our programs, take free host training on the PULSE rhythm, learn to run your community in Creator Lab, get help from a real person, and ask the community in the forum.', 'America/Los_Angeles', '/brand/frequency/logo/frequency-icon-round.png', '/brand/frequency/photos/day-meditation-circle.jpg', '{"theme":"modern","siteStyle":{"theme":"new-world","synced":true,"spaceFonts":"modern"},"megaTheme":{"theme":"new-world","niche":"networks"},"pages":[{"slug":"home","label":"Home","system":true},{"slug":"programs","label":"Programs"},{"slug":"creator-lab","label":"Creator Lab"},{"slug":"business-of-community","label":"Business of Community"},{"slug":"help","label":"Help desk"},{"slug":"about","label":"About"}],"pageDocs":{"home":{"root":{"props":{}},"content":[{"type":"NewWorldHero","props":{"id":"fh-home-hero-0","eyebrow":"Frequency · Programs, training and help","title":"Gather like it *matters.*","lead":"The home base for everyone building Frequency. Find our programs, learn to host on the PULSE rhythm, get help from a real person, and ask the community anything. Start wherever you are.","primaryLabel":"Explore programs","primaryHref":"/spaces/hq/programs","secondaryLabel":"Get help","secondaryHref":"/spaces/hq/help","proof":"Run by the Frequency team, for members, hosts and Spaces.","aside":"We build circles, not walls.","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","badge":"Open to everyone","useEvents":true,"rows":[{"weekday":"Help","mon":"Desk","day":"1","title":"Open a help ticket","body":"A real person reads every ticket.","time":"Any time","where":"Online","spots":"Open","kind":"session","href":"/support"},{"weekday":"Course","mon":"Free","day":"2","title":"The Business of Community 101","body":"Run your community like it’s going to last. Four weeks, free for every Space.","time":"4 weeks · about an hour each","where":"Online","spots":"Open","kind":"session","href":"/journeys/the-business-of-community-101"},{"weekday":"Course","mon":"Free","day":"3","title":"Host Foundations","body":"Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.","time":"Self-paced · 4 parts","where":"Online","spots":"Open","kind":"session","href":"/journeys/host-foundations"}],"register":"auto"}},{"type":"NewWorldStats","props":{"id":"fh-home-stats-1","items":[{"icon":"heart","value":"4","label":"Pillars","note":"Mind, Body, Spirit, Expression"},{"icon":"users","value":"5","label":"beats in every circle","note":"Presence, Unite, Lead, Settle, Exhale"},{"icon":"calendar","value":"4","label":"host courses","note":"Three free online, one in person"},{"icon":"check","value":"1","label":"help desk","note":"A real person answers"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-home-doors-2","index":"01","eyebrow":"Inside","title":"Five *doors.*","lede":"Everything the Frequency team runs for members, hosts and Spaces.","rows":[{"icon":"award","title":"Programs","body":"The Quest, Circles, events and host training: the structured ways to take part."},{"icon":"heart","title":"Host training","body":"Free courses on the PULSE rhythm, care and consent, and the three circle formats."},{"icon":"check","title":"Help desk","body":"Open a ticket, browse the help center, or report something that feels off."},{"icon":"sparkle","title":"Creator Lab","body":"Business and leadership for the people who gather others. Starts with The Business of Community 101."},{"icon":"users","title":"Community forum","body":"Ask a question, share what worked, suggest a feature. Hosts and the team read it."}],"register":"auto"}},{"type":"NewWorldStory","props":{"id":"fh-home-story-3","index":"02","eyebrow":"A community collective","title":"Built by *its members.*","paragraphs":["Frequency is a community collective, not just an app. The software helps people find each other and helps local hosts and businesses run their rooms. The point is the room.","We grow town by town, one circle at a time. Every one of those circles needs someone who arrives early, sets the chairs, starts on time and makes the new person feel expected.","This Space is where that work is shared in the open: the programs, the training, the answers and the conversation."],"buttonLabel":"Our story","buttonHref":"/spaces/hq/about","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","quote":"The structure exists to serve the circle.","quoteBy":"Daniel Tyack · Founder","register":"auto"}},{"type":"SpacePractices","props":{"id":"fh-home-journeys-4","eyebrow":"Learn here","heading":"Courses to start","practicesHeading":"Practices","journeysHeading":"Courses","only":""}},{"type":"NewWorldProcess","props":{"id":"fh-home-path-5","index":"03","eyebrow":"Host training","title":"From guest to *host.*","lede":"","rows":[{"icon":"calendar","title":"Learn","body":"Take Host Foundations, free and self-paced. Four short weeks on the PULSE rhythm."},{"icon":"heart","title":"Learn to care","body":"Take Safe and Well Held: agreements, consent and what to do when something comes up."},{"icon":"users","title":"Co-host","body":"Run two circles beside a trained host. Lead one beat, then two, then the whole night."},{"icon":"award","title":"Host","body":"Open your own circle with a mentor on call, then join the monthly Host Circle."}],"register":"auto"}},{"type":"NewWorldGallery","props":{"id":"fh-home-gallery-6","index":"04","eyebrow":"Real circles","title":"Rooms people *come back to.*","lede":"Photos from Frequency gatherings.","images":[{"image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide"},{"image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck"},{"image":"/brand/frequency/photos/day-parachute-play.jpg","alt":"People holding a rainbow parachute on a clifftop lawn"},{"image":"/brand/frequency/photos/gathering-14.jpg","alt":"A circle on mats around a gong at the water"},{"image":"/brand/frequency/photos/gathering-13.jpg","alt":"A group moving together on the beach at golden hour"}],"register":"auto"}},{"type":"NewWorldFaq","props":{"id":"fh-home-faq-7","index":"05","eyebrow":"Questions","title":"Good to *know.*","lede":"Anything else, ask. A real person answers.","phone":"","email":"hello@frequencylocal.com","hours":"","areasLabel":"","areas":[],"rows":[{"question":"What is this Space?","answer":"The Frequency team''s own Space: our programs, host training, Creator Lab, the help desk and a community forum, in one place. Follow it to hear what''s new."},{"question":"How do I get help with my account?","answer":"Open a help ticket from the help desk. A real person reads every one, and you can follow the reply from your tickets."},{"question":"Do I need experience to host?","answer":"No. Most Frequency hosts started as guests. Host Foundations and the apprenticeship take you from your first seat in the circle to running your own."},{"question":"Can my organization train its own hosts here?","answer":"Yes. The courses and the PULSE rhythm are built so partner organizations and volunteers can use them for their own in-person and online groups."},{"question":"Where do I ask other members a question?","answer":"In the community forum. Post a question, share what worked, or say hello. Hosts and the team read it too."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-home-8","aside":"Generous structure. Real care. On time.","title":"Pick a door. *Come in.*","primaryLabel":"Ask the community","primaryHref":"/spaces/hq/community","secondaryLabel":"Get help","secondaryHref":"/support","note":"","register":"auto"}}]},"programs":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-programs-head-9","index":"","eyebrow":"Frequency Programs","title":"Show up. *Come back.*","lede":"Frequency Programs are the structured ways to take part: The Quest, Circles, local events and host training. Start with one.","register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-programs-rows-a","costLabel":"For","whenLabel":"Rhythm","buttonLabel":"Start","buttonHref":"/circles","secondaryLabel":"Questions","secondaryHref":"/spaces/hq/help","rows":[{"icon":"award","tags":"Program","name":"The Quest","body":"Daily practices and Journeys you take with your Circle, across the four Pillars. Show up, earn Zaps and Gems, and climb the season.","price":"Every member","when":"Daily","image":"/brand/frequency/photos/gathering-13.jpg","alt":"A group moving together on the beach at golden hour","buttonLabel":"How The Quest works","href":"/help/the-quest"},{"icon":"users","tags":"Program","name":"Circles","body":"Small groups of 12 to 18 people who meet at the same time in the same place, on the PULSE rhythm.","price":"Every member","when":"Weekly or every other week","image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide","buttonLabel":"Find a Circle","href":"/circles"},{"icon":"calendar","tags":"Program","name":"What''s happening","body":"Local events from Circles and Spaces near you. RSVP, add it to your calendar, bring someone.","price":"Everyone","when":"Any week","image":"/brand/frequency/photos/day-parachute-play.jpg","alt":"People holding a rainbow parachute on a clifftop lawn","buttonLabel":"See what''s happening","href":"/events"},{"icon":"sparkle","tags":"Program","name":"Creator Lab","body":"Business and leadership for community creators. The Business of Community 101 is free for every Space; paid Spaces add Business Hours on Zoom.","price":"Every Space","when":"One week at a time","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","buttonLabel":"Open Creator Lab","href":"/spaces/hq/creator-lab"},{"icon":"heart","tags":"Program","name":"Host training","body":"Free courses on the PULSE rhythm, care and consent, and the three circle formats, then a co-host apprenticeship.","price":"Hosts and future hosts","when":"Self-paced","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","buttonLabel":"Start host training","href":"/spaces/hq/creator-lab"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-programs-pillars-b","index":"01","eyebrow":"The Quest","title":"Four *Pillars.*","lede":"Every practice and Journey sits under one Pillar, so you build the same strengths all year in different forms.","rows":[{"icon":"sparkle","title":"Mind","body":"Calm down fast, focus, and think clearly. Practices like breathing, journaling and less scrolling."},{"icon":"heart","title":"Body","body":"Move, rest, eat and sleep like you mean it. Walks, stretching, cold water, early nights."},{"icon":"users","title":"Spirit","body":"Meaning, gratitude and time with people. Stillness, service and showing up for each other."},{"icon":"award","title":"Expression","body":"Make something and share it. The weekly Expression Challenge, alone or with your Circle."}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"fh-programs-quest-c","index":"02","eyebrow":"How The Quest works","title":"Small things, *every day.*","lede":"","rows":[{"icon":"calendar","title":"Pick a Journey","body":"Choose one under a Pillar. Each has a few minutes of practice a day."},{"icon":"check","title":"Practice daily","body":"Log it when you do it. Streaks build, and misses are part of it."},{"icon":"users","title":"Bring your Circle","body":"Take a Journey with your Circle and show up for each other in person."},{"icon":"award","title":"Earn as you go","body":"Zaps and Gems for showing up, a Pillar Trophy when you finish a Journey."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-programs-d","aside":"Generous structure. Real care. On time.","title":"Start with *one.*","primaryLabel":"Find a Circle","primaryHref":"/circles","secondaryLabel":"See what''s happening","secondaryHref":"/events","note":"","register":"auto"}}]},"creator-lab":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-lib-head-14","index":"","eyebrow":"Creator Lab","title":"Courses for the people who *gather others.*","lede":"Free courses in two tracks: hosting the room, and running the community behind it. Start anywhere. Every course ends with you doing it for real.","register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-lib-tracks-15","index":"01","eyebrow":"The library","title":"Two *tracks.*","lede":"Each course is free. Paid Spaces add a weekly room on Zoom.","rows":[{"icon":"heart","title":"Hosting","body":"The PULSE rhythm, care and consent, the three circle formats, and an apprenticeship beside a trained host."},{"icon":"sparkle","title":"Business and leadership","body":"The Business of Community: what a gathering costs you, what to charge, who came back, and who to text next week."}],"register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-lib-rows-16","costLabel":"Cost","whenLabel":"Length","buttonLabel":"Start a course","buttonHref":"/spaces/hq/business-of-community","secondaryLabel":"Questions","secondaryHref":"/spaces/hq/help","rows":[{"icon":"calendar","tags":"Business · 4 weeks","name":"The Business of Community 101","body":"Four weeks: The Engine, The Container, The Gathering, The Exchange. Five short lessons a week, about an hour, ending in one commitment.","price":"Free","when":"4 weeks","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","buttonLabel":"See the course","href":"/spaces/hq/business-of-community"},{"icon":"users","tags":"Business · monthly start","name":"This month’s start","body":"Everyone who starts this month moves through it together. A thread to share what you tried, and someone noticing when you don’t.","price":"Free","when":"Starts each month","image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck","buttonLabel":"Join this month","href":"/circles/creator-lab-december-start"},{"icon":"message","tags":"Business · Zoom","name":"Business Hours","body":"Same hour every week. Bring one number and one stuck thing. Commitments read back, one hot seat, a work block, and a new if-then.","price":"Paid Spaces","when":"Tuesdays · 10 AM Pacific","image":"/sites/new-world/photos/cafe-table.webp","alt":"Three people talking at a small table in a cafe","buttonLabel":"See the calendar","href":"/spaces/hq/calendar"},{"icon":"award","tags":"Business · Zoom","name":"Live cohort","body":"Eight to twelve Space owners, four weekly 2.5-hour workshops, ending in the Certified capstone. The pilot runs this December.","price":"Paid Spaces","when":"Four weeks","image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide","buttonLabel":"Ask for a seat","href":"/support"},{"icon":"calendar","tags":"Hosting · Online","name":"Host Foundations","body":"Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/host-foundations"},{"icon":"heart","tags":"Hosting · Online","name":"Safe and Well Held","body":"Agreements, consent and care: how to keep a room safe enough to be honest, and what to do when something comes up.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/gathering-12.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/safe-and-well-held"},{"icon":"users","tags":"Hosting · Online","name":"The Three Circle Formats","body":"Open, Community and Focus Circles: what each one is for, what the host does, and how to choose.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/gathering-03.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/circle-formats"},{"icon":"award","tags":"Hosting · In person","name":"Co-host Apprenticeship","body":"Learn by doing: shadow a trained host, co-lead two circles, then host your own with a mentor on call.","price":"Ask us","when":"Three circles","image":"/brand/frequency/photos/gathering-04.jpg","alt":"","buttonLabel":"Ask about a mentor","href":"/journeys/co-host-apprenticeship"}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"fh-pulse-beats-h","index":"02","eyebrow":"The PULSE rhythm · for everyone","title":"What each beat *is.*","lede":"","rows":[{"icon":"heart","title":"P · Presence","body":"Arrive. A few slow breaths, feet on the floor, phones away. The host sets the tone by going first."},{"icon":"users","title":"U · Unite","body":"A check-in round. Each person says how they''re arriving, and everyone else listens without replying."},{"icon":"award","title":"L · Lead","body":"Tonight''s practice: a teaching, a movement, a conversation or a skill. The part that changes from week to week."},{"icon":"check","title":"S · Settle","body":"Quiet integration. Rest, journal or sit with what came up before anyone has to talk about it."},{"icon":"message","title":"E · Exhale","body":"Close together. One word or one line each, a thank you, and a clear end."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"fh-pulse-host-i","index":"03","eyebrow":"The PULSE rhythm · for the host","title":"What you *do.*","lede":"A 90-minute night, beat by beat.","note":"Shorter night? Trim Lead first. Never skip Exhale.","rows":[{"title":"Presence · 10 min","body":"Start on time. Welcome people by name. Name the purpose of tonight in one sentence."},{"title":"Unite · 20 min","body":"Read the agreements. Ask one question everyone can answer. Keep it lean so everyone gets a turn."},{"title":"Lead · 35 min","body":"Give clear steps, an invitation and an opt-out. Watch the room more than your notes."},{"title":"Settle · 15 min","body":"Lower the pace. Offer a simple prompt. Let silence do some of the work."},{"title":"Exhale · 10 min","body":"End on time. Say what happens next and how people can reach you."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-training-formats-j","index":"04","eyebrow":"One rhythm","title":"Three *formats.*","lede":"Every circle runs on PULSE. The format decides how much you teach and how big the room gets.","rows":[{"icon":"users","title":"Open Circle · 12 to 18 people","body":"The host keeps the room, with no teaching agenda. People come to be heard and to hear each other. You open and close, keep the agreements and the time, and pass the turn. You speak least."},{"icon":"heart","title":"Community Circle · 12 to 18 people","body":"A hosted circle around one shared theme: moon circles, men''s and women''s circles, grief, new parents, sharing circles. You choose the theme and the question for the round, and keep the circle on it."},{"icon":"award","title":"Focus Circle · Up to 50 people","body":"The host teaches a modality: breathwork, sound, movement, a skill. The PULSE rhythm wraps the teaching so the room still feels like a circle. You teach in the Lead beat, and the four beats around it keep it personal and safe."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-training-agreements-k","index":"05","eyebrow":"Read at every circle","title":"Six *agreements.*","lede":"","rows":[{"icon":"check","title":"Every practice is an invitation","body":"Join in, go gently, watch, or pass. No one needs a reason."},{"icon":"heart","title":"What is shared stays here","body":"Take the lessons home. Leave the stories and the names in the room."},{"icon":"users","title":"Speak for yourself","body":"Use I. Speak from your own life, not about anyone else''s."},{"icon":"message","title":"No fixing","body":"Listen without advising, correcting or rescuing. Ask an honest question, or simply say thank you."},{"icon":"calendar","title":"Start and end on time","body":"A clear start and a clear end are a kindness. People can plan around you."},{"icon":"award","title":"Ask before touch","body":"No touch without a clear yes, every time. Nothing sexual happens in a circle."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"fh-training-care-l","index":"06","eyebrow":"When something comes up","title":"Safe enough *to be honest.*","lede":"Our training follows the six principles of a trauma-informed approach: safety, trust and transparency, peer support, collaboration, choice and voice, and culture and context.","note":"A Frequency circle is practice and community, not therapy or crisis care. In the US, call or text 988 for the Suicide and Crisis Lifeline. If anyone is in immediate danger, call emergency services.","rows":[{"title":"Strong feelings","body":"Slow down. Let the person finish, thank them, and offer a breath for the whole circle. Tears aren''t an emergency."},{"title":"A disclosure","body":"Thank them, don''t press for details in the circle, and speak privately afterwards. Share the local crisis line."},{"title":"One voice filling the room","body":"Use the talking piece. Set a time per share before the round starts. Invite someone who hasn’t spoken yet."},{"title":"After a hard night","body":"Debrief with your co-host or mentor within a day. Hosting is a team practice."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-creator-lab-17","aside":"Generous structure. Real care. On time.","title":"Start with *one course.*","primaryLabel":"The Business of Community","primaryHref":"/spaces/hq/business-of-community","secondaryLabel":"Start Host Foundations","secondaryHref":"/journeys/host-foundations","note":"","register":"auto"}}]},"business-of-community":{"root":{"props":{}},"content":[{"type":"NewWorldHero","props":{"id":"boc-hero-0","eyebrow":"Free course · The Business of Community 101","title":"A full room. *A night that still didn’t pay.*","lead":"A free four-week course for people who already gather others. Learn what a night really costs you, what to charge, who came back, and who to text next week. About an hour a week.","primaryLabel":"Start the course","primaryHref":"/journeys/the-business-of-community-101","secondaryLabel":"Join this month","secondaryHref":"/circles/creator-lab-december-start","proof":"","aside":"","image":"/sites/new-world/photos/backyard-class.webp","alt":"A teacher leads a stretching class on mats and rugs on a sunny backyard patio","badge":"Free for every Space","useEvents":false,"rows":[{"weekday":"Course","mon":"Free","day":"1","title":"The Business of Community 101","body":"Four weeks, five short lessons each.","time":"Self-paced · about an hour a week","where":"Online","spots":"Open","kind":"session","href":"/journeys/the-business-of-community-101"},{"weekday":"Circle","mon":"Free","day":"2","title":"This month’s start","body":"Start with others who began this month.","time":"Starts each month","where":"Online","spots":"Open","kind":"session","href":"/circles/creator-lab-december-start"},{"weekday":"Zoom","mon":"Tue","day":"3","title":"Business Hours","body":"A weekly hour for paid Spaces.","time":"Tuesdays · 10 AM Pacific","where":"Zoom","spots":"Paid Spaces","kind":"session","href":"/spaces/hq/calendar"}],"areas":[],"register":"auto"}},{"type":"NewWorldStats","props":{"id":"boc-facts-1","items":[{"icon":"heart","value":"Free","label":"for every Space","note":"Every lesson, every week"},{"icon":"calendar","value":"4","label":"weeks","note":"One idea each"},{"icon":"check","value":"5","label":"short lessons a week","note":"Story, tools, practice, build, commit"},{"icon":"clock","value":"1","label":"hour a week, about","note":"Spreadsheet and phone are enough"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"boc-pain-2","index":"01","eyebrow":"Sound familiar?","title":"Three ways a good room *wears you out.*","lede":"People love what you run. That part is working. These are the parts nobody taught you.","rows":[{"icon":"tag","title":"A full room that doesn''t cover the night","body":"Rent, gear, snacks, your drive, your hours. The room was packed and you still came home behind."},{"icon":"heart","title":"You carry all of it","body":"Booking, texting, setup, the money, the hard conversations. It all runs through you, and nobody covers when you need a week off."},{"icon":"message","title":"The loudest guest runs the room","body":"Nobody said the rules out loud, so the person with the most opinions made them. Quieter people stop coming back."}],"register":"auto"}},{"type":"NewWorldLongStory","props":{"id":"boc-idea-3","index":"02","eyebrow":"The one idea","title":"Frequency. Not the sound kind. *The how-often kind.*","paragraphs":["Most people who gather others count heads. How many came. How many RSVP''d. How full it looked.","The question isn''t how many came. It''s how many came back. A small room where people return is healthier than a big room you never see again.","Return frequency is the number this course is built around. Every week gives you one more way to keep people coming back without running yourself into the ground."],"register":"auto"}},{"type":"NewWorldQuote","props":{"id":"boc-quote-4","label":"In Daniel’s words","quote":"The question isn''t how many came. It''s *how many came back.*","by":"Daniel Tyack · Founder","register":"auto"}},{"type":"NewWorldStory","props":{"id":"boc-weeks-5","index":"03","eyebrow":"The four weeks","title":"Four weeks. *One idea each.*","paragraphs":["Week 1, The Engine. Structure isn''t the opposite of soul. It''s what keeps the soul from burning out.","Week 2, The Container. A container isn''t what you believe. It''s what you''ve written down, said out loud, and will enforce.","Week 3, The Gathering. Whatever authority you don''t hold, the loudest guest will.","Week 4, The Exchange. Charging is what makes your presence renewable."],"buttonLabel":"Start the course","buttonHref":"/journeys/the-business-of-community-101","secondaryLabel":"Join this month’s start","secondaryHref":"/circles/creator-lab-december-start","image":"/sites/new-world/photos/workshop-table.webp","alt":"Adults and kids making crafts around a long table in a workshop room","quote":"","quoteBy":"","register":"auto"}},{"type":"NewWorldAlways","props":{"id":"boc-leave-6","index":"04","eyebrow":"By the end","title":"Four things *you will know.*","items":["What a gathering costs you","What you charge","Who came back","Who to text next week"],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"boc-who-7","index":"05","eyebrow":"Who it''s for","title":"People who *already gather.*","lede":"Local creators running their thing solo or nearly, with somewhere between ten and a hundred and fifty people.","rows":[{"icon":"heart","title":"Yoga and breathwork teachers","body":"Classes, workshops and retreats you mostly run yourself."},{"icon":"sparkle","title":"Sound healers","body":"Sound baths and circles in studios, homes and parks."},{"icon":"users","title":"Dance and meetup organizers","body":"The regular night people plan their week around."},{"icon":"star","title":"Musicians and open mic hosts","body":"The list, the room, the regulars and the newcomers."},{"icon":"award","title":"Makers","body":"Workshops, classes and craft nights around a table."},{"icon":"pin","title":"House and small venues","body":"A living room, a backyard or a small room that hosts others."}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"boc-each-week-8","index":"06","eyebrow":"How each week works","title":"Five short lessons. *About an hour.*","lede":"It works on a spreadsheet and a phone. The build steps happen inside your own Space.","rows":[{"icon":"eye","title":"The idea","body":"A short story, stopped right at the decision. What would you do?"},{"icon":"check","title":"Four tools","body":"Plain, small tools you can use before your next gathering."},{"icon":"message","title":"Practice out loud","body":"Say the hard sentence before you need it in the room."},{"icon":"calendar","title":"Build it on Frequency","body":"Set it up inside your own Space, so it keeps working after the lesson."},{"icon":"heart","title":"One commitment","body":"Write one commitment down and say it to another person."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"boc-finish-9","index":"07","eyebrow":"Two ways to finish","title":"Attended or *Certified.*","lede":"Pick the one that fits your season.","note":"Certified is a certificate of completion and competency from Frequency. It is not an accredited certification.","rows":[{"title":"Attended","body":"Finish all four weeks. That counts as 10 contact hours."},{"title":"Certified","body":"Submit your Community Book: four one-page sheets plus a 13-week season plan, and do the four builds in your own Space. Review is free through January 31, 2027, then comes with a paid Space."}],"register":"auto"}},{"type":"NewWorldTools","props":{"id":"boc-paid-a","index":"08","eyebrow":"With a paid Space","title":"The course is free. *A paid Space adds a room.*","lede":"The course works on your own. A paid Space adds a regular hour with other Space owners. Plans live on the pricing page.","buttonLabel":"See plans","buttonHref":"/pricing","secondaryLabel":"Ask for a seat","secondaryHref":"/support","note":"Live sessions are on Zoom. Times are Pacific. Check the calendar for the next one.","rows":[{"icon":"clock","title":"Business Hours","body":"Every Tuesday, 10 AM Pacific, on Zoom. Bring one number and one stuck thing."},{"icon":"users","title":"The live pilot cohort","body":"8 to 12 Space owners on Zoom this December. Thursdays Dec 3, 10, 17 and Jan 7, 10:00 to 12:30 Pacific."},{"icon":"check","title":"The course stays free","body":"Every lesson, and this month’s start, is open to every Space."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"boc-faq-b","index":"09","eyebrow":"Questions","title":"Good to *know.*","lede":"Anything else, ask. A real person answers.","rows":[{"icon":"tag","title":"What does it cost?","body":"Nothing. The course and this month’s start are free for every Space. Certified review is free through January 31, 2027, then comes with a paid Space."},{"icon":"clock","title":"How much time each week?","body":"About an hour: five short lessons. Do them in one sitting or spread them out."},{"icon":"pin","title":"Do I need a Space?","body":"The build steps happen inside your own Space, and Certified needs the four builds done there. The rest works on a spreadsheet and a phone."},{"icon":"award","title":"Is it accredited?","body":"No. Certified is a certificate of completion and competency from Frequency, not an accredited certification."},{"icon":"calendar","title":"What if I miss a week?","body":"Pick it up where you left off. The lessons wait for you."},{"icon":"eye","title":"Is it live or self-paced?","body":"Self-paced. Paid Spaces can add a live hour each week and a seat in the live pilot cohort on Zoom."},{"icon":"message","title":"What is Business Hours?","body":"A weekly hour on Zoom for paid Spaces, Tuesdays at 10 AM Pacific. Bring one number and one stuck thing."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"boc-closer-c","aside":"Free. Four weeks. About an hour each.","title":"Keep the room. *Keep yourself.*","primaryLabel":"Start the course","primaryHref":"/journeys/the-business-of-community-101","secondaryLabel":"Ask a question","secondaryHref":"/spaces/hq/help","note":"Want company? This month’s start is free too.","register":"auto"}}]},"help":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-help-head-u","index":"","eyebrow":"Help desk","title":"Ask. *A person answers.*","lede":"Open a help ticket, browse the help center, or ask the community. Every ticket is read by a real person on the Frequency team.","register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-help-rows-v","costLabel":"Cost","whenLabel":"Best for","buttonLabel":"Open a help ticket","buttonHref":"/support","secondaryLabel":"Common questions","secondaryHref":"#faq","rows":[{"icon":"message","tags":"Help desk","name":"Open a help ticket","body":"Tell us what happened. Follow every reply from your tickets.","price":"Free","when":"Your account, billing, bugs","image":"/sites/new-world/photos/cafe-table.webp","alt":"Three people talking at a small table in a cafe","buttonLabel":"Open a ticket","href":"/support"},{"icon":"check","tags":"Help center","name":"Browse the help center","body":"Plain answers on Circles, events, Spaces, The Quest and membership.","price":"Free","when":"How-to questions","image":"/sites/new-world/photos/garden-picnic.webp","alt":"People gathered on rugs and cushions in a leafy backyard garden","buttonLabel":"Open the help center","href":"/help"},{"icon":"users","tags":"Forum","name":"Ask the community","body":"Post a question or an idea. Members, hosts and the team answer.","price":"Free","when":"Ideas and how others do it","image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck","buttonLabel":"Go to the forum","href":"/spaces/hq/community"},{"icon":"heart","tags":"Safety","name":"Report a safety concern","body":"Reporting, blocking and how moderation works. In an emergency, call emergency services first.","price":"Free","when":"Anything that feels unsafe","image":"/sites/new-world/photos/fire-circle.webp","alt":"People sitting quietly around a fire pit in the evening","buttonLabel":"Safety and reporting","href":"/help/safety"}],"register":"auto"}},{"type":"NewWorldPosts","props":{"id":"fh-help-center-w","index":"01","eyebrow":"Help center","title":"Find it *fast.*","lede":"Seven topics, written in plain words.","buttonLabel":"Open the help center","buttonHref":"/help","rows":[{"kind":"Start here","title":"Getting started: what Frequency is and how to find your people","meta":"","href":"/help/getting-started"},{"kind":"Groups","title":"Circles and events: how gatherings work","meta":"","href":"/help/groups"},{"kind":"Hosting","title":"Leading a Circle: start one, run the first night, keep it going","meta":"","href":"/help/leading"},{"kind":"Spaces","title":"Running a Space: the tools a Space gives you","meta":"","href":"/help/spaces"},{"kind":"The Quest","title":"Zaps, Gems, ranks and rewards","meta":"","href":"/help/the-quest"},{"kind":"Membership","title":"What''s free and what Crew adds","meta":"","href":"/help/membership"},{"kind":"Safety","title":"Reporting, blocking and how moderation works","meta":"","href":"/help/safety"}],"register":"auto"}},{"type":"NewWorldFaq","props":{"id":"fh-help-faq-x","index":"02","eyebrow":"Questions","title":"Good to *know.*","lede":"Still stuck? Open a ticket or email us.","phone":"","email":"hello@frequencylocal.com","hours":"","areasLabel":"","areas":[],"rows":[{"question":"How do I open a help ticket?","answer":"Go to Help and support, describe what happened, and send it. You can follow every reply from your tickets on the same page."},{"question":"Something feels unsafe. What do I do?","answer":"Use Report on the post, profile or event, or open a ticket marked safety. If anyone is in immediate danger, call emergency services first."},{"question":"I have a billing question.","answer":"Open a ticket and choose billing. Include the email on your account so we can find it quickly."},{"question":"How do I start a Space for my business or group?","answer":"Read Running a Space in the help center, then create one from the Spaces page. The help desk can walk you through it."},{"question":"Can I suggest a feature?","answer":"Yes, please. Post it in the community forum so others can add to it, or open a ticket if it is about your own account."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-help-y","aside":"Generous structure. Real care. On time.","title":"Still stuck? *Ask us.*","primaryLabel":"Open a help ticket","primaryHref":"/support","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","note":"","register":"auto"}}]},"about":{"root":{"props":{}},"content":[{"type":"NewWorldAboutHero","props":{"id":"fh-about-hero-z","eyebrow":"Our story · Frequency","title":"Build circles, *not walls.*","lead":"Frequency is a community collective that spreads town by town through local hosts. This Space is where the team shares the programs, the training, the answers and the conversation in the open.","chips":[{"icon":"check","text":"Free to start"},{"icon":"users","text":"Run with its members"},{"icon":"heart","text":"Care designed in"}],"primaryLabel":"Explore programs","primaryHref":"/spaces/hq/programs","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","image":"/sites/new-world/photos/circle-sunrise.webp","alt":"A wide circle of people seated on a plaza at sunrise","name":"Daniel Tyack","role":"Founder","register":"auto"}},{"type":"NewWorldLongStory","props":{"id":"fh-about-roots-10","index":"01","eyebrow":"Where this comes from","title":"Old practices, *plain words.*","paragraphs":["Sitting in a circle and taking turns to speak is one of the oldest ways people have gathered. We did not invent it. We gave it a rhythm, PULSE, that a new host can learn in a week and a returning guest can trust.","Our host training draws on a few sources worth reading in full. The Way of Council, as taught by Jack Zimmerman and Virginia Coyle, gives us the talking piece and its intentions. Parker Palmer and the Center for Courage and Renewal give us touchstones for trustworthy space, like no fixing and honest, open questions. Priya Parker gives us generous authority: a host who protects, connects and equalizes the room. SAMHSA gives us the six principles of a trauma-informed approach.","Everything is written in plain words, because a host should be able to read an agreement aloud without explaining it."],"register":"auto"}},{"type":"NewWorldQuote","props":{"id":"fh-about-quote-11","label":"In Daniel’s words","quote":"The structure exists to serve the circle. The circle *governs the structure.*","by":"Daniel Tyack · Founder","register":"auto"}},{"type":"NewWorldTeam","props":{"id":"fh-about-team-12","index":"02","eyebrow":"The team","title":"Who *runs this.*","lede":"","note":"Trained hosts join this list as they become mentors.","rows":[{"name":"Daniel Tyack","role":"Founder · The Janitor","image":"/brand/frequency/photos/daniel-tyack.jpg","alt":"Daniel Tyack smiling"}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-about-13","aside":"Generous structure. Real care. On time.","title":"Pick a door. *Come in.*","primaryLabel":"Ask the community","primaryHref":"/spaces/hq/community","secondaryLabel":"Get help","secondaryHref":"/support","note":"","register":"auto"}}]}},"siteHero":{"eyebrow":"Frequency · Programs, training and help","heading":"Gather like it *matters.*","tagline":"Our programs, free host training, a help desk with real people and a community forum, in one place.","action":{"label":"Explore programs","href":"/spaces/hq/programs"},"secondary":{"label":"Get help","href":"/spaces/hq/help"}},"headerCta":{"kind":"custom","url":"/support","label":"Get help"},"coverFocus":"50% 45%","coverScrim":"none","coverSize":"hero","logoBackdrop":"none","profileLayout":{"rows":[{"id":"r0","columns":1,"cells":[["editorial"]]},{"id":"r1","columns":1,"cells":[["links"]],"title":"Start here","headerOn":true},{"id":"r2","columns":1,"cells":[["cardGrid"]]},{"id":"r3","columns":1,"cells":[["practices"]]},{"id":"r4","columns":1,"cells":[["zigzag"]]},{"id":"r5","columns":1,"cells":[["offerings"]]},{"id":"r6","columns":1,"cells":[["quote"]]},{"id":"r7","columns":1,"cells":[["faq"]]},{"id":"r8","columns":1,"cells":[["accentBeat"]]},{"id":"r9","columns":2,"cells":[["contact"],["team"]],"title":"Contact and team","headerOn":true}],"content":{"about":{"eyebrow":"About","title":"About this Space","body":"This is the Frequency team''s own Space: the home base for everyone building Frequency. Find our programs, take free host training on the PULSE rhythm, learn to run your community in Creator Lab, get help from a real person, and ask the community in the forum."},"editorial":{"eyebrow":"The Frequency Space","title":"Gather like it matters.","body":"This is the Frequency team''s own Space: the home base for members, hosts and Spaces.<br><br>Find our programs, take free host training on the PULSE rhythm, open a help ticket when something breaks, and ask the community anything in the forum. Everything here is free to walk into."},"links":{"items":[{"label":"Open a help ticket","url":"/support"},{"label":"Ask the community","url":"/spaces/hq/community"},{"label":"Start host training","url":"/journeys/host-foundations"},{"label":"Help center","url":"/help"},{"label":"Creator Lab","url":"/spaces/hq/creator-lab"},{"label":"Find a Circle","url":"/circles"}]},"cardGrid":{"eyebrow":"Inside","title":"Five doors.","subtitle":"Everything the Frequency team runs for members, hosts and Spaces.","columns":"3","shadow":false,"cards":[{"icon":"1","title":"Programs","text":"The Quest, Circles, events and host training: the structured ways to take part."},{"icon":"2","title":"Host training","text":"Free courses on the PULSE rhythm, care and consent, and the three circle formats."},{"icon":"3","title":"Help desk","text":"Open a ticket, browse the help center, or report something that feels off. A real person answers."},{"icon":"4","title":"Creator Lab","text":"Business and leadership for community creators, starting with The Business of Community 101. Free for every Space."},{"icon":"5","title":"Community forum","text":"Ask a question, share what worked, suggest a feature. Hosts and the team read it."}]},"practices":{"eyebrow":"Learn here","title":"Courses to start"},"zigzag":{"eyebrow":"The PULSE rhythm","title":"Five beats. Every circle.","body":"<b>Presence.</b> Arrive. A few slow breaths, feet on the floor, phones away. The host sets the tone by going first.<br><br><b>Unite.</b> A check-in round. Each person says how they''re arriving, and everyone else listens without replying.<br><br><b>Lead.</b> Tonight''s practice: a teaching, a movement, a conversation or a skill. The part that changes from week to week.<br><br><b>Settle.</b> Quiet integration. Rest, journal or sit with what came up before anyone has to talk about it.<br><br><b>Exhale.</b> Close together. One word or one line each, a thank you, and a clear end.","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","mediaSide":"right"},"offerings":{"eyebrow":"Frequency Programs","title":"Show up. Come back."},"quote":{"text":"The structure exists to serve the circle. The circle governs the structure.","by":"Daniel Tyack · Founder"},"faq":{"eyebrow":"Questions","title":"Good to know"},"accentBeat":{"eyebrow":"Help desk","title":"Need a hand?","body":"Open a help ticket and a real person on the Frequency team answers. You can follow every reply from your tickets.","buttonOn":true,"buttonLabel":"Open a help ticket","buttonUrl":"/support"},"contact":{"eyebrow":"Contact","title":"Reach the team"},"team":{"eyebrow":"The team","title":"Who runs this"}}},"websiteEditor":{"v":1,"revision":1,"draft":{"theme":"NewWorld","brand":{"logo":"/brand/frequency/logo/frequency-icon-round.png","accent":"#1AA7C0"},"chrome":{"name":"Frequency","tagline":"Gather like it matters.","cta":{"label":"Get help","href":"/support"}},"pages":[{"slug":"home","label":"Home","doc":{"root":{"props":{}},"content":[{"type":"NewWorldHero","props":{"id":"fh-home-hero-18","eyebrow":"Frequency · Programs, training and help","title":"Gather like it *matters.*","lead":"The home base for everyone building Frequency. Find our programs, learn to host on the PULSE rhythm, get help from a real person, and ask the community anything. Start wherever you are.","primaryLabel":"Explore programs","primaryHref":"/spaces/hq/programs","secondaryLabel":"Get help","secondaryHref":"/spaces/hq/help","proof":"Run by the Frequency team, for members, hosts and Spaces.","aside":"We build circles, not walls.","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","badge":"Open to everyone","useEvents":true,"rows":[{"weekday":"Help","mon":"Desk","day":"1","title":"Open a help ticket","body":"A real person reads every ticket.","time":"Any time","where":"Online","spots":"Open","kind":"session","href":"/support"},{"weekday":"Course","mon":"Free","day":"2","title":"The Business of Community 101","body":"Run your community like it’s going to last. Four weeks, free for every Space.","time":"4 weeks · about an hour each","where":"Online","spots":"Open","kind":"session","href":"/journeys/the-business-of-community-101"},{"weekday":"Course","mon":"Free","day":"3","title":"Host Foundations","body":"Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.","time":"Self-paced · 4 parts","where":"Online","spots":"Open","kind":"session","href":"/journeys/host-foundations"}],"register":"auto"}},{"type":"NewWorldStats","props":{"id":"fh-home-stats-19","items":[{"icon":"heart","value":"4","label":"Pillars","note":"Mind, Body, Spirit, Expression"},{"icon":"users","value":"5","label":"beats in every circle","note":"Presence, Unite, Lead, Settle, Exhale"},{"icon":"calendar","value":"4","label":"host courses","note":"Three free online, one in person"},{"icon":"check","value":"1","label":"help desk","note":"A real person answers"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-home-doors-1a","index":"01","eyebrow":"Inside","title":"Five *doors.*","lede":"Everything the Frequency team runs for members, hosts and Spaces.","rows":[{"icon":"award","title":"Programs","body":"The Quest, Circles, events and host training: the structured ways to take part."},{"icon":"heart","title":"Host training","body":"Free courses on the PULSE rhythm, care and consent, and the three circle formats."},{"icon":"check","title":"Help desk","body":"Open a ticket, browse the help center, or report something that feels off."},{"icon":"sparkle","title":"Creator Lab","body":"Business and leadership for the people who gather others. Starts with The Business of Community 101."},{"icon":"users","title":"Community forum","body":"Ask a question, share what worked, suggest a feature. Hosts and the team read it."}],"register":"auto"}},{"type":"NewWorldStory","props":{"id":"fh-home-story-1b","index":"02","eyebrow":"A community collective","title":"Built by *its members.*","paragraphs":["Frequency is a community collective, not just an app. The software helps people find each other and helps local hosts and businesses run their rooms. The point is the room.","We grow town by town, one circle at a time. Every one of those circles needs someone who arrives early, sets the chairs, starts on time and makes the new person feel expected.","This Space is where that work is shared in the open: the programs, the training, the answers and the conversation."],"buttonLabel":"Our story","buttonHref":"/spaces/hq/about","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","quote":"The structure exists to serve the circle.","quoteBy":"Daniel Tyack · Founder","register":"auto"}},{"type":"SpacePractices","props":{"id":"fh-home-journeys-1c","eyebrow":"Learn here","heading":"Courses to start","practicesHeading":"Practices","journeysHeading":"Courses","only":""}},{"type":"NewWorldProcess","props":{"id":"fh-home-path-1d","index":"03","eyebrow":"Host training","title":"From guest to *host.*","lede":"","rows":[{"icon":"calendar","title":"Learn","body":"Take Host Foundations, free and self-paced. Four short weeks on the PULSE rhythm."},{"icon":"heart","title":"Learn to care","body":"Take Safe and Well Held: agreements, consent and what to do when something comes up."},{"icon":"users","title":"Co-host","body":"Run two circles beside a trained host. Lead one beat, then two, then the whole night."},{"icon":"award","title":"Host","body":"Open your own circle with a mentor on call, then join the monthly Host Circle."}],"register":"auto"}},{"type":"NewWorldGallery","props":{"id":"fh-home-gallery-1e","index":"04","eyebrow":"Real circles","title":"Rooms people *come back to.*","lede":"Photos from Frequency gatherings.","images":[{"image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide"},{"image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck"},{"image":"/brand/frequency/photos/day-parachute-play.jpg","alt":"People holding a rainbow parachute on a clifftop lawn"},{"image":"/brand/frequency/photos/gathering-14.jpg","alt":"A circle on mats around a gong at the water"},{"image":"/brand/frequency/photos/gathering-13.jpg","alt":"A group moving together on the beach at golden hour"}],"register":"auto"}},{"type":"NewWorldFaq","props":{"id":"fh-home-faq-1f","index":"05","eyebrow":"Questions","title":"Good to *know.*","lede":"Anything else, ask. A real person answers.","phone":"","email":"hello@frequencylocal.com","hours":"","areasLabel":"","areas":[],"rows":[{"question":"What is this Space?","answer":"The Frequency team''s own Space: our programs, host training, Creator Lab, the help desk and a community forum, in one place. Follow it to hear what''s new."},{"question":"How do I get help with my account?","answer":"Open a help ticket from the help desk. A real person reads every one, and you can follow the reply from your tickets."},{"question":"Do I need experience to host?","answer":"No. Most Frequency hosts started as guests. Host Foundations and the apprenticeship take you from your first seat in the circle to running your own."},{"question":"Can my organization train its own hosts here?","answer":"Yes. The courses and the PULSE rhythm are built so partner organizations and volunteers can use them for their own in-person and online groups."},{"question":"Where do I ask other members a question?","answer":"In the community forum. Post a question, share what worked, or say hello. Hosts and the team read it too."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-home-1g","aside":"Generous structure. Real care. On time.","title":"Pick a door. *Come in.*","primaryLabel":"Ask the community","primaryHref":"/spaces/hq/community","secondaryLabel":"Get help","secondaryHref":"/support","note":"","register":"auto"}}]},"seo":{"title":"Frequency","description":"Frequency: programs, free host training, Creator Lab, a help desk and a community forum."},"comments":[]},{"slug":"programs","label":"Programs","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-programs-head-1h","index":"","eyebrow":"Frequency Programs","title":"Show up. *Come back.*","lede":"Frequency Programs are the structured ways to take part: The Quest, Circles, local events and host training. Start with one.","register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-programs-rows-1i","costLabel":"For","whenLabel":"Rhythm","buttonLabel":"Start","buttonHref":"/circles","secondaryLabel":"Questions","secondaryHref":"/spaces/hq/help","rows":[{"icon":"award","tags":"Program","name":"The Quest","body":"Daily practices and Journeys you take with your Circle, across the four Pillars. Show up, earn Zaps and Gems, and climb the season.","price":"Every member","when":"Daily","image":"/brand/frequency/photos/gathering-13.jpg","alt":"A group moving together on the beach at golden hour","buttonLabel":"How The Quest works","href":"/help/the-quest"},{"icon":"users","tags":"Program","name":"Circles","body":"Small groups of 12 to 18 people who meet at the same time in the same place, on the PULSE rhythm.","price":"Every member","when":"Weekly or every other week","image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide","buttonLabel":"Find a Circle","href":"/circles"},{"icon":"calendar","tags":"Program","name":"What''s happening","body":"Local events from Circles and Spaces near you. RSVP, add it to your calendar, bring someone.","price":"Everyone","when":"Any week","image":"/brand/frequency/photos/day-parachute-play.jpg","alt":"People holding a rainbow parachute on a clifftop lawn","buttonLabel":"See what''s happening","href":"/events"},{"icon":"sparkle","tags":"Program","name":"Creator Lab","body":"Business and leadership for community creators. The Business of Community 101 is free for every Space; paid Spaces add Business Hours on Zoom.","price":"Every Space","when":"One week at a time","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","buttonLabel":"Open Creator Lab","href":"/spaces/hq/creator-lab"},{"icon":"heart","tags":"Program","name":"Host training","body":"Free courses on the PULSE rhythm, care and consent, and the three circle formats, then a co-host apprenticeship.","price":"Hosts and future hosts","when":"Self-paced","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","buttonLabel":"Start host training","href":"/spaces/hq/creator-lab"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-programs-pillars-1j","index":"01","eyebrow":"The Quest","title":"Four *Pillars.*","lede":"Every practice and Journey sits under one Pillar, so you build the same strengths all year in different forms.","rows":[{"icon":"sparkle","title":"Mind","body":"Calm down fast, focus, and think clearly. Practices like breathing, journaling and less scrolling."},{"icon":"heart","title":"Body","body":"Move, rest, eat and sleep like you mean it. Walks, stretching, cold water, early nights."},{"icon":"users","title":"Spirit","body":"Meaning, gratitude and time with people. Stillness, service and showing up for each other."},{"icon":"award","title":"Expression","body":"Make something and share it. The weekly Expression Challenge, alone or with your Circle."}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"fh-programs-quest-1k","index":"02","eyebrow":"How The Quest works","title":"Small things, *every day.*","lede":"","rows":[{"icon":"calendar","title":"Pick a Journey","body":"Choose one under a Pillar. Each has a few minutes of practice a day."},{"icon":"check","title":"Practice daily","body":"Log it when you do it. Streaks build, and misses are part of it."},{"icon":"users","title":"Bring your Circle","body":"Take a Journey with your Circle and show up for each other in person."},{"icon":"award","title":"Earn as you go","body":"Zaps and Gems for showing up, a Pillar Trophy when you finish a Journey."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-programs-1l","aside":"Generous structure. Real care. On time.","title":"Start with *one.*","primaryLabel":"Find a Circle","primaryHref":"/circles","secondaryLabel":"See what''s happening","secondaryHref":"/events","note":"","register":"auto"}}]},"seo":{"title":"Programs · Frequency","description":"Frequency Programs: The Quest, Circles, local events and host training."},"comments":[]},{"slug":"creator-lab","label":"Creator Lab","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-lib-head-2c","index":"","eyebrow":"Creator Lab","title":"Courses for the people who *gather others.*","lede":"Free courses in two tracks: hosting the room, and running the community behind it. Start anywhere. Every course ends with you doing it for real.","register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-lib-tracks-2d","index":"01","eyebrow":"The library","title":"Two *tracks.*","lede":"Each course is free. Paid Spaces add a weekly room on Zoom.","rows":[{"icon":"heart","title":"Hosting","body":"The PULSE rhythm, care and consent, the three circle formats, and an apprenticeship beside a trained host."},{"icon":"sparkle","title":"Business and leadership","body":"The Business of Community: what a gathering costs you, what to charge, who came back, and who to text next week."}],"register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-lib-rows-2e","costLabel":"Cost","whenLabel":"Length","buttonLabel":"Start a course","buttonHref":"/spaces/hq/business-of-community","secondaryLabel":"Questions","secondaryHref":"/spaces/hq/help","rows":[{"icon":"calendar","tags":"Business · 4 weeks","name":"The Business of Community 101","body":"Four weeks: The Engine, The Container, The Gathering, The Exchange. Five short lessons a week, about an hour, ending in one commitment.","price":"Free","when":"4 weeks","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","buttonLabel":"See the course","href":"/spaces/hq/business-of-community"},{"icon":"users","tags":"Business · monthly start","name":"This month’s start","body":"Everyone who starts this month moves through it together. A thread to share what you tried, and someone noticing when you don’t.","price":"Free","when":"Starts each month","image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck","buttonLabel":"Join this month","href":"/circles/creator-lab-december-start"},{"icon":"message","tags":"Business · Zoom","name":"Business Hours","body":"Same hour every week. Bring one number and one stuck thing. Commitments read back, one hot seat, a work block, and a new if-then.","price":"Paid Spaces","when":"Tuesdays · 10 AM Pacific","image":"/sites/new-world/photos/cafe-table.webp","alt":"Three people talking at a small table in a cafe","buttonLabel":"See the calendar","href":"/spaces/hq/calendar"},{"icon":"award","tags":"Business · Zoom","name":"Live cohort","body":"Eight to twelve Space owners, four weekly 2.5-hour workshops, ending in the Certified capstone. The pilot runs this December.","price":"Paid Spaces","when":"Four weeks","image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide","buttonLabel":"Ask for a seat","href":"/support"},{"icon":"calendar","tags":"Hosting · Online","name":"Host Foundations","body":"Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/host-foundations"},{"icon":"heart","tags":"Hosting · Online","name":"Safe and Well Held","body":"Agreements, consent and care: how to keep a room safe enough to be honest, and what to do when something comes up.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/gathering-12.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/safe-and-well-held"},{"icon":"users","tags":"Hosting · Online","name":"The Three Circle Formats","body":"Open, Community and Focus Circles: what each one is for, what the host does, and how to choose.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/gathering-03.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/circle-formats"},{"icon":"award","tags":"Hosting · In person","name":"Co-host Apprenticeship","body":"Learn by doing: shadow a trained host, co-lead two circles, then host your own with a mentor on call.","price":"Ask us","when":"Three circles","image":"/brand/frequency/photos/gathering-04.jpg","alt":"","buttonLabel":"Ask about a mentor","href":"/journeys/co-host-apprenticeship"}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"fh-pulse-beats-1p","index":"02","eyebrow":"The PULSE rhythm · for everyone","title":"What each beat *is.*","lede":"","rows":[{"icon":"heart","title":"P · Presence","body":"Arrive. A few slow breaths, feet on the floor, phones away. The host sets the tone by going first."},{"icon":"users","title":"U · Unite","body":"A check-in round. Each person says how they''re arriving, and everyone else listens without replying."},{"icon":"award","title":"L · Lead","body":"Tonight''s practice: a teaching, a movement, a conversation or a skill. The part that changes from week to week."},{"icon":"check","title":"S · Settle","body":"Quiet integration. Rest, journal or sit with what came up before anyone has to talk about it."},{"icon":"message","title":"E · Exhale","body":"Close together. One word or one line each, a thank you, and a clear end."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"fh-pulse-host-1q","index":"03","eyebrow":"The PULSE rhythm · for the host","title":"What you *do.*","lede":"A 90-minute night, beat by beat.","note":"Shorter night? Trim Lead first. Never skip Exhale.","rows":[{"title":"Presence · 10 min","body":"Start on time. Welcome people by name. Name the purpose of tonight in one sentence."},{"title":"Unite · 20 min","body":"Read the agreements. Ask one question everyone can answer. Keep it lean so everyone gets a turn."},{"title":"Lead · 35 min","body":"Give clear steps, an invitation and an opt-out. Watch the room more than your notes."},{"title":"Settle · 15 min","body":"Lower the pace. Offer a simple prompt. Let silence do some of the work."},{"title":"Exhale · 10 min","body":"End on time. Say what happens next and how people can reach you."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-training-formats-1r","index":"04","eyebrow":"One rhythm","title":"Three *formats.*","lede":"Every circle runs on PULSE. The format decides how much you teach and how big the room gets.","rows":[{"icon":"users","title":"Open Circle · 12 to 18 people","body":"The host keeps the room, with no teaching agenda. People come to be heard and to hear each other. You open and close, keep the agreements and the time, and pass the turn. You speak least."},{"icon":"heart","title":"Community Circle · 12 to 18 people","body":"A hosted circle around one shared theme: moon circles, men''s and women''s circles, grief, new parents, sharing circles. You choose the theme and the question for the round, and keep the circle on it."},{"icon":"award","title":"Focus Circle · Up to 50 people","body":"The host teaches a modality: breathwork, sound, movement, a skill. The PULSE rhythm wraps the teaching so the room still feels like a circle. You teach in the Lead beat, and the four beats around it keep it personal and safe."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-training-agreements-1s","index":"05","eyebrow":"Read at every circle","title":"Six *agreements.*","lede":"","rows":[{"icon":"check","title":"Every practice is an invitation","body":"Join in, go gently, watch, or pass. No one needs a reason."},{"icon":"heart","title":"What is shared stays here","body":"Take the lessons home. Leave the stories and the names in the room."},{"icon":"users","title":"Speak for yourself","body":"Use I. Speak from your own life, not about anyone else''s."},{"icon":"message","title":"No fixing","body":"Listen without advising, correcting or rescuing. Ask an honest question, or simply say thank you."},{"icon":"calendar","title":"Start and end on time","body":"A clear start and a clear end are a kindness. People can plan around you."},{"icon":"award","title":"Ask before touch","body":"No touch without a clear yes, every time. Nothing sexual happens in a circle."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"fh-training-care-1t","index":"06","eyebrow":"When something comes up","title":"Safe enough *to be honest.*","lede":"Our training follows the six principles of a trauma-informed approach: safety, trust and transparency, peer support, collaboration, choice and voice, and culture and context.","note":"A Frequency circle is practice and community, not therapy or crisis care. In the US, call or text 988 for the Suicide and Crisis Lifeline. If anyone is in immediate danger, call emergency services.","rows":[{"title":"Strong feelings","body":"Slow down. Let the person finish, thank them, and offer a breath for the whole circle. Tears aren''t an emergency."},{"title":"A disclosure","body":"Thank them, don''t press for details in the circle, and speak privately afterwards. Share the local crisis line."},{"title":"One voice filling the room","body":"Use the talking piece. Set a time per share before the round starts. Invite someone who hasn’t spoken yet."},{"title":"After a hard night","body":"Debrief with your co-host or mentor within a day. Hosting is a team practice."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-creator-lab-2f","aside":"Generous structure. Real care. On time.","title":"Start with *one course.*","primaryLabel":"The Business of Community","primaryHref":"/spaces/hq/business-of-community","secondaryLabel":"Start Host Foundations","secondaryHref":"/journeys/host-foundations","note":"","register":"auto"}}]},"seo":{"title":"Creator Lab · Frequency","description":"Creator Lab: free courses for the people who gather others. Hosting on the PULSE rhythm, and The Business of Community."},"comments":[]},{"slug":"business-of-community","label":"Business of Community","doc":{"root":{"props":{}},"content":[{"type":"NewWorldHero","props":{"id":"boc-hero-0","eyebrow":"Free course · The Business of Community 101","title":"A full room. *A night that still didn’t pay.*","lead":"A free four-week course for people who already gather others. Learn what a night really costs you, what to charge, who came back, and who to text next week. About an hour a week.","primaryLabel":"Start the course","primaryHref":"/journeys/the-business-of-community-101","secondaryLabel":"Join this month","secondaryHref":"/circles/creator-lab-december-start","proof":"","aside":"","image":"/sites/new-world/photos/backyard-class.webp","alt":"A teacher leads a stretching class on mats and rugs on a sunny backyard patio","badge":"Free for every Space","useEvents":false,"rows":[{"weekday":"Course","mon":"Free","day":"1","title":"The Business of Community 101","body":"Four weeks, five short lessons each.","time":"Self-paced · about an hour a week","where":"Online","spots":"Open","kind":"session","href":"/journeys/the-business-of-community-101"},{"weekday":"Circle","mon":"Free","day":"2","title":"This month’s start","body":"Start with others who began this month.","time":"Starts each month","where":"Online","spots":"Open","kind":"session","href":"/circles/creator-lab-december-start"},{"weekday":"Zoom","mon":"Tue","day":"3","title":"Business Hours","body":"A weekly hour for paid Spaces.","time":"Tuesdays · 10 AM Pacific","where":"Zoom","spots":"Paid Spaces","kind":"session","href":"/spaces/hq/calendar"}],"areas":[],"register":"auto"}},{"type":"NewWorldStats","props":{"id":"boc-facts-1","items":[{"icon":"heart","value":"Free","label":"for every Space","note":"Every lesson, every week"},{"icon":"calendar","value":"4","label":"weeks","note":"One idea each"},{"icon":"check","value":"5","label":"short lessons a week","note":"Story, tools, practice, build, commit"},{"icon":"clock","value":"1","label":"hour a week, about","note":"Spreadsheet and phone are enough"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"boc-pain-2","index":"01","eyebrow":"Sound familiar?","title":"Three ways a good room *wears you out.*","lede":"People love what you run. That part is working. These are the parts nobody taught you.","rows":[{"icon":"tag","title":"A full room that doesn''t cover the night","body":"Rent, gear, snacks, your drive, your hours. The room was packed and you still came home behind."},{"icon":"heart","title":"You carry all of it","body":"Booking, texting, setup, the money, the hard conversations. It all runs through you, and nobody covers when you need a week off."},{"icon":"message","title":"The loudest guest runs the room","body":"Nobody said the rules out loud, so the person with the most opinions made them. Quieter people stop coming back."}],"register":"auto"}},{"type":"NewWorldLongStory","props":{"id":"boc-idea-3","index":"02","eyebrow":"The one idea","title":"Frequency. Not the sound kind. *The how-often kind.*","paragraphs":["Most people who gather others count heads. How many came. How many RSVP''d. How full it looked.","The question isn''t how many came. It''s how many came back. A small room where people return is healthier than a big room you never see again.","Return frequency is the number this course is built around. Every week gives you one more way to keep people coming back without running yourself into the ground."],"register":"auto"}},{"type":"NewWorldQuote","props":{"id":"boc-quote-4","label":"In Daniel’s words","quote":"The question isn''t how many came. It''s *how many came back.*","by":"Daniel Tyack · Founder","register":"auto"}},{"type":"NewWorldStory","props":{"id":"boc-weeks-5","index":"03","eyebrow":"The four weeks","title":"Four weeks. *One idea each.*","paragraphs":["Week 1, The Engine. Structure isn''t the opposite of soul. It''s what keeps the soul from burning out.","Week 2, The Container. A container isn''t what you believe. It''s what you''ve written down, said out loud, and will enforce.","Week 3, The Gathering. Whatever authority you don''t hold, the loudest guest will.","Week 4, The Exchange. Charging is what makes your presence renewable."],"buttonLabel":"Start the course","buttonHref":"/journeys/the-business-of-community-101","secondaryLabel":"Join this month’s start","secondaryHref":"/circles/creator-lab-december-start","image":"/sites/new-world/photos/workshop-table.webp","alt":"Adults and kids making crafts around a long table in a workshop room","quote":"","quoteBy":"","register":"auto"}},{"type":"NewWorldAlways","props":{"id":"boc-leave-6","index":"04","eyebrow":"By the end","title":"Four things *you will know.*","items":["What a gathering costs you","What you charge","Who came back","Who to text next week"],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"boc-who-7","index":"05","eyebrow":"Who it''s for","title":"People who *already gather.*","lede":"Local creators running their thing solo or nearly, with somewhere between ten and a hundred and fifty people.","rows":[{"icon":"heart","title":"Yoga and breathwork teachers","body":"Classes, workshops and retreats you mostly run yourself."},{"icon":"sparkle","title":"Sound healers","body":"Sound baths and circles in studios, homes and parks."},{"icon":"users","title":"Dance and meetup organizers","body":"The regular night people plan their week around."},{"icon":"star","title":"Musicians and open mic hosts","body":"The list, the room, the regulars and the newcomers."},{"icon":"award","title":"Makers","body":"Workshops, classes and craft nights around a table."},{"icon":"pin","title":"House and small venues","body":"A living room, a backyard or a small room that hosts others."}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"boc-each-week-8","index":"06","eyebrow":"How each week works","title":"Five short lessons. *About an hour.*","lede":"It works on a spreadsheet and a phone. The build steps happen inside your own Space.","rows":[{"icon":"eye","title":"The idea","body":"A short story, stopped right at the decision. What would you do?"},{"icon":"check","title":"Four tools","body":"Plain, small tools you can use before your next gathering."},{"icon":"message","title":"Practice out loud","body":"Say the hard sentence before you need it in the room."},{"icon":"calendar","title":"Build it on Frequency","body":"Set it up inside your own Space, so it keeps working after the lesson."},{"icon":"heart","title":"One commitment","body":"Write one commitment down and say it to another person."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"boc-finish-9","index":"07","eyebrow":"Two ways to finish","title":"Attended or *Certified.*","lede":"Pick the one that fits your season.","note":"Certified is a certificate of completion and competency from Frequency. It is not an accredited certification.","rows":[{"title":"Attended","body":"Finish all four weeks. That counts as 10 contact hours."},{"title":"Certified","body":"Submit your Community Book: four one-page sheets plus a 13-week season plan, and do the four builds in your own Space. Review is free through January 31, 2027, then comes with a paid Space."}],"register":"auto"}},{"type":"NewWorldTools","props":{"id":"boc-paid-a","index":"08","eyebrow":"With a paid Space","title":"The course is free. *A paid Space adds a room.*","lede":"The course works on your own. A paid Space adds a regular hour with other Space owners. Plans live on the pricing page.","buttonLabel":"See plans","buttonHref":"/pricing","secondaryLabel":"Ask for a seat","secondaryHref":"/support","note":"Live sessions are on Zoom. Times are Pacific. Check the calendar for the next one.","rows":[{"icon":"clock","title":"Business Hours","body":"Every Tuesday, 10 AM Pacific, on Zoom. Bring one number and one stuck thing."},{"icon":"users","title":"The live pilot cohort","body":"8 to 12 Space owners on Zoom this December. Thursdays Dec 3, 10, 17 and Jan 7, 10:00 to 12:30 Pacific."},{"icon":"check","title":"The course stays free","body":"Every lesson, and this month’s start, is open to every Space."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"boc-faq-b","index":"09","eyebrow":"Questions","title":"Good to *know.*","lede":"Anything else, ask. A real person answers.","rows":[{"icon":"tag","title":"What does it cost?","body":"Nothing. The course and this month’s start are free for every Space. Certified review is free through January 31, 2027, then comes with a paid Space."},{"icon":"clock","title":"How much time each week?","body":"About an hour: five short lessons. Do them in one sitting or spread them out."},{"icon":"pin","title":"Do I need a Space?","body":"The build steps happen inside your own Space, and Certified needs the four builds done there. The rest works on a spreadsheet and a phone."},{"icon":"award","title":"Is it accredited?","body":"No. Certified is a certificate of completion and competency from Frequency, not an accredited certification."},{"icon":"calendar","title":"What if I miss a week?","body":"Pick it up where you left off. The lessons wait for you."},{"icon":"eye","title":"Is it live or self-paced?","body":"Self-paced. Paid Spaces can add a live hour each week and a seat in the live pilot cohort on Zoom."},{"icon":"message","title":"What is Business Hours?","body":"A weekly hour on Zoom for paid Spaces, Tuesdays at 10 AM Pacific. Bring one number and one stuck thing."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"boc-closer-c","aside":"Free. Four weeks. About an hour each.","title":"Keep the room. *Keep yourself.*","primaryLabel":"Start the course","primaryHref":"/journeys/the-business-of-community-101","secondaryLabel":"Ask a question","secondaryHref":"/spaces/hq/help","note":"Want company? This month’s start is free too.","register":"auto"}}]},"seo":{"title":"The Business of Community 101 · Frequency","description":"A free four-week course for people who already gather others. Know what a night costs you, what to charge, who came back, and who to text next week."},"comments":[]},{"slug":"help","label":"Help desk","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-help-head-22","index":"","eyebrow":"Help desk","title":"Ask. *A person answers.*","lede":"Open a help ticket, browse the help center, or ask the community. Every ticket is read by a real person on the Frequency team.","register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-help-rows-23","costLabel":"Cost","whenLabel":"Best for","buttonLabel":"Open a help ticket","buttonHref":"/support","secondaryLabel":"Common questions","secondaryHref":"#faq","rows":[{"icon":"message","tags":"Help desk","name":"Open a help ticket","body":"Tell us what happened. Follow every reply from your tickets.","price":"Free","when":"Your account, billing, bugs","image":"/sites/new-world/photos/cafe-table.webp","alt":"Three people talking at a small table in a cafe","buttonLabel":"Open a ticket","href":"/support"},{"icon":"check","tags":"Help center","name":"Browse the help center","body":"Plain answers on Circles, events, Spaces, The Quest and membership.","price":"Free","when":"How-to questions","image":"/sites/new-world/photos/garden-picnic.webp","alt":"People gathered on rugs and cushions in a leafy backyard garden","buttonLabel":"Open the help center","href":"/help"},{"icon":"users","tags":"Forum","name":"Ask the community","body":"Post a question or an idea. Members, hosts and the team answer.","price":"Free","when":"Ideas and how others do it","image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck","buttonLabel":"Go to the forum","href":"/spaces/hq/community"},{"icon":"heart","tags":"Safety","name":"Report a safety concern","body":"Reporting, blocking and how moderation works. In an emergency, call emergency services first.","price":"Free","when":"Anything that feels unsafe","image":"/sites/new-world/photos/fire-circle.webp","alt":"People sitting quietly around a fire pit in the evening","buttonLabel":"Safety and reporting","href":"/help/safety"}],"register":"auto"}},{"type":"NewWorldPosts","props":{"id":"fh-help-center-24","index":"01","eyebrow":"Help center","title":"Find it *fast.*","lede":"Seven topics, written in plain words.","buttonLabel":"Open the help center","buttonHref":"/help","rows":[{"kind":"Start here","title":"Getting started: what Frequency is and how to find your people","meta":"","href":"/help/getting-started"},{"kind":"Groups","title":"Circles and events: how gatherings work","meta":"","href":"/help/groups"},{"kind":"Hosting","title":"Leading a Circle: start one, run the first night, keep it going","meta":"","href":"/help/leading"},{"kind":"Spaces","title":"Running a Space: the tools a Space gives you","meta":"","href":"/help/spaces"},{"kind":"The Quest","title":"Zaps, Gems, ranks and rewards","meta":"","href":"/help/the-quest"},{"kind":"Membership","title":"What''s free and what Crew adds","meta":"","href":"/help/membership"},{"kind":"Safety","title":"Reporting, blocking and how moderation works","meta":"","href":"/help/safety"}],"register":"auto"}},{"type":"NewWorldFaq","props":{"id":"fh-help-faq-25","index":"02","eyebrow":"Questions","title":"Good to *know.*","lede":"Still stuck? Open a ticket or email us.","phone":"","email":"hello@frequencylocal.com","hours":"","areasLabel":"","areas":[],"rows":[{"question":"How do I open a help ticket?","answer":"Go to Help and support, describe what happened, and send it. You can follow every reply from your tickets on the same page."},{"question":"Something feels unsafe. What do I do?","answer":"Use Report on the post, profile or event, or open a ticket marked safety. If anyone is in immediate danger, call emergency services first."},{"question":"I have a billing question.","answer":"Open a ticket and choose billing. Include the email on your account so we can find it quickly."},{"question":"How do I start a Space for my business or group?","answer":"Read Running a Space in the help center, then create one from the Spaces page. The help desk can walk you through it."},{"question":"Can I suggest a feature?","answer":"Yes, please. Post it in the community forum so others can add to it, or open a ticket if it is about your own account."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-help-26","aside":"Generous structure. Real care. On time.","title":"Still stuck? *Ask us.*","primaryLabel":"Open a help ticket","primaryHref":"/support","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","note":"","register":"auto"}}]},"seo":{"title":"Help desk · Frequency","description":"Open a help ticket, browse the help center, or ask the community."},"comments":[]},{"slug":"about","label":"About","doc":{"root":{"props":{}},"content":[{"type":"NewWorldAboutHero","props":{"id":"fh-about-hero-27","eyebrow":"Our story · Frequency","title":"Build circles, *not walls.*","lead":"Frequency is a community collective that spreads town by town through local hosts. This Space is where the team shares the programs, the training, the answers and the conversation in the open.","chips":[{"icon":"check","text":"Free to start"},{"icon":"users","text":"Run with its members"},{"icon":"heart","text":"Care designed in"}],"primaryLabel":"Explore programs","primaryHref":"/spaces/hq/programs","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","image":"/sites/new-world/photos/circle-sunrise.webp","alt":"A wide circle of people seated on a plaza at sunrise","name":"Daniel Tyack","role":"Founder","register":"auto"}},{"type":"NewWorldLongStory","props":{"id":"fh-about-roots-28","index":"01","eyebrow":"Where this comes from","title":"Old practices, *plain words.*","paragraphs":["Sitting in a circle and taking turns to speak is one of the oldest ways people have gathered. We did not invent it. We gave it a rhythm, PULSE, that a new host can learn in a week and a returning guest can trust.","Our host training draws on a few sources worth reading in full. The Way of Council, as taught by Jack Zimmerman and Virginia Coyle, gives us the talking piece and its intentions. Parker Palmer and the Center for Courage and Renewal give us touchstones for trustworthy space, like no fixing and honest, open questions. Priya Parker gives us generous authority: a host who protects, connects and equalizes the room. SAMHSA gives us the six principles of a trauma-informed approach.","Everything is written in plain words, because a host should be able to read an agreement aloud without explaining it."],"register":"auto"}},{"type":"NewWorldQuote","props":{"id":"fh-about-quote-29","label":"In Daniel’s words","quote":"The structure exists to serve the circle. The circle *governs the structure.*","by":"Daniel Tyack · Founder","register":"auto"}},{"type":"NewWorldTeam","props":{"id":"fh-about-team-2a","index":"02","eyebrow":"The team","title":"Who *runs this.*","lede":"","note":"Trained hosts join this list as they become mentors.","rows":[{"name":"Daniel Tyack","role":"Founder · The Janitor","image":"/brand/frequency/photos/daniel-tyack.jpg","alt":"Daniel Tyack smiling"}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-about-2b","aside":"Generous structure. Real care. On time.","title":"Pick a door. *Come in.*","primaryLabel":"Ask the community","primaryHref":"/spaces/hq/community","secondaryLabel":"Get help","secondaryHref":"/support","note":"","register":"auto"}}]},"seo":{"title":"About · Frequency","description":"Frequency is a community collective. Build circles, not walls."},"comments":[]}]},"published":{"theme":"NewWorld","brand":{"logo":"/brand/frequency/logo/frequency-icon-round.png","accent":"#1AA7C0"},"chrome":{"name":"Frequency","tagline":"Gather like it matters.","cta":{"label":"Get help","href":"/support"}},"pages":[{"slug":"home","label":"Home","doc":{"root":{"props":{}},"content":[{"type":"NewWorldHero","props":{"id":"fh-home-hero-18","eyebrow":"Frequency · Programs, training and help","title":"Gather like it *matters.*","lead":"The home base for everyone building Frequency. Find our programs, learn to host on the PULSE rhythm, get help from a real person, and ask the community anything. Start wherever you are.","primaryLabel":"Explore programs","primaryHref":"/spaces/hq/programs","secondaryLabel":"Get help","secondaryHref":"/spaces/hq/help","proof":"Run by the Frequency team, for members, hosts and Spaces.","aside":"We build circles, not walls.","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","badge":"Open to everyone","useEvents":true,"rows":[{"weekday":"Help","mon":"Desk","day":"1","title":"Open a help ticket","body":"A real person reads every ticket.","time":"Any time","where":"Online","spots":"Open","kind":"session","href":"/support"},{"weekday":"Course","mon":"Free","day":"2","title":"The Business of Community 101","body":"Run your community like it’s going to last. Four weeks, free for every Space.","time":"4 weeks · about an hour each","where":"Online","spots":"Open","kind":"session","href":"/journeys/the-business-of-community-101"},{"weekday":"Course","mon":"Free","day":"3","title":"Host Foundations","body":"Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.","time":"Self-paced · 4 parts","where":"Online","spots":"Open","kind":"session","href":"/journeys/host-foundations"}],"register":"auto"}},{"type":"NewWorldStats","props":{"id":"fh-home-stats-19","items":[{"icon":"heart","value":"4","label":"Pillars","note":"Mind, Body, Spirit, Expression"},{"icon":"users","value":"5","label":"beats in every circle","note":"Presence, Unite, Lead, Settle, Exhale"},{"icon":"calendar","value":"4","label":"host courses","note":"Three free online, one in person"},{"icon":"check","value":"1","label":"help desk","note":"A real person answers"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-home-doors-1a","index":"01","eyebrow":"Inside","title":"Five *doors.*","lede":"Everything the Frequency team runs for members, hosts and Spaces.","rows":[{"icon":"award","title":"Programs","body":"The Quest, Circles, events and host training: the structured ways to take part."},{"icon":"heart","title":"Host training","body":"Free courses on the PULSE rhythm, care and consent, and the three circle formats."},{"icon":"check","title":"Help desk","body":"Open a ticket, browse the help center, or report something that feels off."},{"icon":"sparkle","title":"Creator Lab","body":"Business and leadership for the people who gather others. Starts with The Business of Community 101."},{"icon":"users","title":"Community forum","body":"Ask a question, share what worked, suggest a feature. Hosts and the team read it."}],"register":"auto"}},{"type":"NewWorldStory","props":{"id":"fh-home-story-1b","index":"02","eyebrow":"A community collective","title":"Built by *its members.*","paragraphs":["Frequency is a community collective, not just an app. The software helps people find each other and helps local hosts and businesses run their rooms. The point is the room.","We grow town by town, one circle at a time. Every one of those circles needs someone who arrives early, sets the chairs, starts on time and makes the new person feel expected.","This Space is where that work is shared in the open: the programs, the training, the answers and the conversation."],"buttonLabel":"Our story","buttonHref":"/spaces/hq/about","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","quote":"The structure exists to serve the circle.","quoteBy":"Daniel Tyack · Founder","register":"auto"}},{"type":"SpacePractices","props":{"id":"fh-home-journeys-1c","eyebrow":"Learn here","heading":"Courses to start","practicesHeading":"Practices","journeysHeading":"Courses","only":""}},{"type":"NewWorldProcess","props":{"id":"fh-home-path-1d","index":"03","eyebrow":"Host training","title":"From guest to *host.*","lede":"","rows":[{"icon":"calendar","title":"Learn","body":"Take Host Foundations, free and self-paced. Four short weeks on the PULSE rhythm."},{"icon":"heart","title":"Learn to care","body":"Take Safe and Well Held: agreements, consent and what to do when something comes up."},{"icon":"users","title":"Co-host","body":"Run two circles beside a trained host. Lead one beat, then two, then the whole night."},{"icon":"award","title":"Host","body":"Open your own circle with a mentor on call, then join the monthly Host Circle."}],"register":"auto"}},{"type":"NewWorldGallery","props":{"id":"fh-home-gallery-1e","index":"04","eyebrow":"Real circles","title":"Rooms people *come back to.*","lede":"Photos from Frequency gatherings.","images":[{"image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide"},{"image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck"},{"image":"/brand/frequency/photos/day-parachute-play.jpg","alt":"People holding a rainbow parachute on a clifftop lawn"},{"image":"/brand/frequency/photos/gathering-14.jpg","alt":"A circle on mats around a gong at the water"},{"image":"/brand/frequency/photos/gathering-13.jpg","alt":"A group moving together on the beach at golden hour"}],"register":"auto"}},{"type":"NewWorldFaq","props":{"id":"fh-home-faq-1f","index":"05","eyebrow":"Questions","title":"Good to *know.*","lede":"Anything else, ask. A real person answers.","phone":"","email":"hello@frequencylocal.com","hours":"","areasLabel":"","areas":[],"rows":[{"question":"What is this Space?","answer":"The Frequency team''s own Space: our programs, host training, Creator Lab, the help desk and a community forum, in one place. Follow it to hear what''s new."},{"question":"How do I get help with my account?","answer":"Open a help ticket from the help desk. A real person reads every one, and you can follow the reply from your tickets."},{"question":"Do I need experience to host?","answer":"No. Most Frequency hosts started as guests. Host Foundations and the apprenticeship take you from your first seat in the circle to running your own."},{"question":"Can my organization train its own hosts here?","answer":"Yes. The courses and the PULSE rhythm are built so partner organizations and volunteers can use them for their own in-person and online groups."},{"question":"Where do I ask other members a question?","answer":"In the community forum. Post a question, share what worked, or say hello. Hosts and the team read it too."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-home-1g","aside":"Generous structure. Real care. On time.","title":"Pick a door. *Come in.*","primaryLabel":"Ask the community","primaryHref":"/spaces/hq/community","secondaryLabel":"Get help","secondaryHref":"/support","note":"","register":"auto"}}]},"seo":{"title":"Frequency","description":"Frequency: programs, free host training, Creator Lab, a help desk and a community forum."},"comments":[]},{"slug":"programs","label":"Programs","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-programs-head-1h","index":"","eyebrow":"Frequency Programs","title":"Show up. *Come back.*","lede":"Frequency Programs are the structured ways to take part: The Quest, Circles, local events and host training. Start with one.","register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-programs-rows-1i","costLabel":"For","whenLabel":"Rhythm","buttonLabel":"Start","buttonHref":"/circles","secondaryLabel":"Questions","secondaryHref":"/spaces/hq/help","rows":[{"icon":"award","tags":"Program","name":"The Quest","body":"Daily practices and Journeys you take with your Circle, across the four Pillars. Show up, earn Zaps and Gems, and climb the season.","price":"Every member","when":"Daily","image":"/brand/frequency/photos/gathering-13.jpg","alt":"A group moving together on the beach at golden hour","buttonLabel":"How The Quest works","href":"/help/the-quest"},{"icon":"users","tags":"Program","name":"Circles","body":"Small groups of 12 to 18 people who meet at the same time in the same place, on the PULSE rhythm.","price":"Every member","when":"Weekly or every other week","image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide","buttonLabel":"Find a Circle","href":"/circles"},{"icon":"calendar","tags":"Program","name":"What''s happening","body":"Local events from Circles and Spaces near you. RSVP, add it to your calendar, bring someone.","price":"Everyone","when":"Any week","image":"/brand/frequency/photos/day-parachute-play.jpg","alt":"People holding a rainbow parachute on a clifftop lawn","buttonLabel":"See what''s happening","href":"/events"},{"icon":"sparkle","tags":"Program","name":"Creator Lab","body":"Business and leadership for community creators. The Business of Community 101 is free for every Space; paid Spaces add Business Hours on Zoom.","price":"Every Space","when":"One week at a time","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","buttonLabel":"Open Creator Lab","href":"/spaces/hq/creator-lab"},{"icon":"heart","tags":"Program","name":"Host training","body":"Free courses on the PULSE rhythm, care and consent, and the three circle formats, then a co-host apprenticeship.","price":"Hosts and future hosts","when":"Self-paced","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","buttonLabel":"Start host training","href":"/spaces/hq/creator-lab"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-programs-pillars-1j","index":"01","eyebrow":"The Quest","title":"Four *Pillars.*","lede":"Every practice and Journey sits under one Pillar, so you build the same strengths all year in different forms.","rows":[{"icon":"sparkle","title":"Mind","body":"Calm down fast, focus, and think clearly. Practices like breathing, journaling and less scrolling."},{"icon":"heart","title":"Body","body":"Move, rest, eat and sleep like you mean it. Walks, stretching, cold water, early nights."},{"icon":"users","title":"Spirit","body":"Meaning, gratitude and time with people. Stillness, service and showing up for each other."},{"icon":"award","title":"Expression","body":"Make something and share it. The weekly Expression Challenge, alone or with your Circle."}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"fh-programs-quest-1k","index":"02","eyebrow":"How The Quest works","title":"Small things, *every day.*","lede":"","rows":[{"icon":"calendar","title":"Pick a Journey","body":"Choose one under a Pillar. Each has a few minutes of practice a day."},{"icon":"check","title":"Practice daily","body":"Log it when you do it. Streaks build, and misses are part of it."},{"icon":"users","title":"Bring your Circle","body":"Take a Journey with your Circle and show up for each other in person."},{"icon":"award","title":"Earn as you go","body":"Zaps and Gems for showing up, a Pillar Trophy when you finish a Journey."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-programs-1l","aside":"Generous structure. Real care. On time.","title":"Start with *one.*","primaryLabel":"Find a Circle","primaryHref":"/circles","secondaryLabel":"See what''s happening","secondaryHref":"/events","note":"","register":"auto"}}]},"seo":{"title":"Programs · Frequency","description":"Frequency Programs: The Quest, Circles, local events and host training."},"comments":[]},{"slug":"creator-lab","label":"Creator Lab","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-lib-head-2c","index":"","eyebrow":"Creator Lab","title":"Courses for the people who *gather others.*","lede":"Free courses in two tracks: hosting the room, and running the community behind it. Start anywhere. Every course ends with you doing it for real.","register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-lib-tracks-2d","index":"01","eyebrow":"The library","title":"Two *tracks.*","lede":"Each course is free. Paid Spaces add a weekly room on Zoom.","rows":[{"icon":"heart","title":"Hosting","body":"The PULSE rhythm, care and consent, the three circle formats, and an apprenticeship beside a trained host."},{"icon":"sparkle","title":"Business and leadership","body":"The Business of Community: what a gathering costs you, what to charge, who came back, and who to text next week."}],"register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-lib-rows-2e","costLabel":"Cost","whenLabel":"Length","buttonLabel":"Start a course","buttonHref":"/spaces/hq/business-of-community","secondaryLabel":"Questions","secondaryHref":"/spaces/hq/help","rows":[{"icon":"calendar","tags":"Business · 4 weeks","name":"The Business of Community 101","body":"Four weeks: The Engine, The Container, The Gathering, The Exchange. Five short lessons a week, about an hour, ending in one commitment.","price":"Free","when":"4 weeks","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","buttonLabel":"See the course","href":"/spaces/hq/business-of-community"},{"icon":"users","tags":"Business · monthly start","name":"This month’s start","body":"Everyone who starts this month moves through it together. A thread to share what you tried, and someone noticing when you don’t.","price":"Free","when":"Starts each month","image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck","buttonLabel":"Join this month","href":"/circles/creator-lab-december-start"},{"icon":"message","tags":"Business · Zoom","name":"Business Hours","body":"Same hour every week. Bring one number and one stuck thing. Commitments read back, one hot seat, a work block, and a new if-then.","price":"Paid Spaces","when":"Tuesdays · 10 AM Pacific","image":"/sites/new-world/photos/cafe-table.webp","alt":"Three people talking at a small table in a cafe","buttonLabel":"See the calendar","href":"/spaces/hq/calendar"},{"icon":"award","tags":"Business · Zoom","name":"Live cohort","body":"Eight to twelve Space owners, four weekly 2.5-hour workshops, ending in the Certified capstone. The pilot runs this December.","price":"Paid Spaces","when":"Four weeks","image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide","buttonLabel":"Ask for a seat","href":"/support"},{"icon":"calendar","tags":"Hosting · Online","name":"Host Foundations","body":"Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/host-foundations"},{"icon":"heart","tags":"Hosting · Online","name":"Safe and Well Held","body":"Agreements, consent and care: how to keep a room safe enough to be honest, and what to do when something comes up.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/gathering-12.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/safe-and-well-held"},{"icon":"users","tags":"Hosting · Online","name":"The Three Circle Formats","body":"Open, Community and Focus Circles: what each one is for, what the host does, and how to choose.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/gathering-03.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/circle-formats"},{"icon":"award","tags":"Hosting · In person","name":"Co-host Apprenticeship","body":"Learn by doing: shadow a trained host, co-lead two circles, then host your own with a mentor on call.","price":"Ask us","when":"Three circles","image":"/brand/frequency/photos/gathering-04.jpg","alt":"","buttonLabel":"Ask about a mentor","href":"/journeys/co-host-apprenticeship"}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"fh-pulse-beats-1p","index":"02","eyebrow":"The PULSE rhythm · for everyone","title":"What each beat *is.*","lede":"","rows":[{"icon":"heart","title":"P · Presence","body":"Arrive. A few slow breaths, feet on the floor, phones away. The host sets the tone by going first."},{"icon":"users","title":"U · Unite","body":"A check-in round. Each person says how they''re arriving, and everyone else listens without replying."},{"icon":"award","title":"L · Lead","body":"Tonight''s practice: a teaching, a movement, a conversation or a skill. The part that changes from week to week."},{"icon":"check","title":"S · Settle","body":"Quiet integration. Rest, journal or sit with what came up before anyone has to talk about it."},{"icon":"message","title":"E · Exhale","body":"Close together. One word or one line each, a thank you, and a clear end."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"fh-pulse-host-1q","index":"03","eyebrow":"The PULSE rhythm · for the host","title":"What you *do.*","lede":"A 90-minute night, beat by beat.","note":"Shorter night? Trim Lead first. Never skip Exhale.","rows":[{"title":"Presence · 10 min","body":"Start on time. Welcome people by name. Name the purpose of tonight in one sentence."},{"title":"Unite · 20 min","body":"Read the agreements. Ask one question everyone can answer. Keep it lean so everyone gets a turn."},{"title":"Lead · 35 min","body":"Give clear steps, an invitation and an opt-out. Watch the room more than your notes."},{"title":"Settle · 15 min","body":"Lower the pace. Offer a simple prompt. Let silence do some of the work."},{"title":"Exhale · 10 min","body":"End on time. Say what happens next and how people can reach you."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-training-formats-1r","index":"04","eyebrow":"One rhythm","title":"Three *formats.*","lede":"Every circle runs on PULSE. The format decides how much you teach and how big the room gets.","rows":[{"icon":"users","title":"Open Circle · 12 to 18 people","body":"The host keeps the room, with no teaching agenda. People come to be heard and to hear each other. You open and close, keep the agreements and the time, and pass the turn. You speak least."},{"icon":"heart","title":"Community Circle · 12 to 18 people","body":"A hosted circle around one shared theme: moon circles, men''s and women''s circles, grief, new parents, sharing circles. You choose the theme and the question for the round, and keep the circle on it."},{"icon":"award","title":"Focus Circle · Up to 50 people","body":"The host teaches a modality: breathwork, sound, movement, a skill. The PULSE rhythm wraps the teaching so the room still feels like a circle. You teach in the Lead beat, and the four beats around it keep it personal and safe."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-training-agreements-1s","index":"05","eyebrow":"Read at every circle","title":"Six *agreements.*","lede":"","rows":[{"icon":"check","title":"Every practice is an invitation","body":"Join in, go gently, watch, or pass. No one needs a reason."},{"icon":"heart","title":"What is shared stays here","body":"Take the lessons home. Leave the stories and the names in the room."},{"icon":"users","title":"Speak for yourself","body":"Use I. Speak from your own life, not about anyone else''s."},{"icon":"message","title":"No fixing","body":"Listen without advising, correcting or rescuing. Ask an honest question, or simply say thank you."},{"icon":"calendar","title":"Start and end on time","body":"A clear start and a clear end are a kindness. People can plan around you."},{"icon":"award","title":"Ask before touch","body":"No touch without a clear yes, every time. Nothing sexual happens in a circle."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"fh-training-care-1t","index":"06","eyebrow":"When something comes up","title":"Safe enough *to be honest.*","lede":"Our training follows the six principles of a trauma-informed approach: safety, trust and transparency, peer support, collaboration, choice and voice, and culture and context.","note":"A Frequency circle is practice and community, not therapy or crisis care. In the US, call or text 988 for the Suicide and Crisis Lifeline. If anyone is in immediate danger, call emergency services.","rows":[{"title":"Strong feelings","body":"Slow down. Let the person finish, thank them, and offer a breath for the whole circle. Tears aren''t an emergency."},{"title":"A disclosure","body":"Thank them, don''t press for details in the circle, and speak privately afterwards. Share the local crisis line."},{"title":"One voice filling the room","body":"Use the talking piece. Set a time per share before the round starts. Invite someone who hasn’t spoken yet."},{"title":"After a hard night","body":"Debrief with your co-host or mentor within a day. Hosting is a team practice."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-creator-lab-2f","aside":"Generous structure. Real care. On time.","title":"Start with *one course.*","primaryLabel":"The Business of Community","primaryHref":"/spaces/hq/business-of-community","secondaryLabel":"Start Host Foundations","secondaryHref":"/journeys/host-foundations","note":"","register":"auto"}}]},"seo":{"title":"Creator Lab · Frequency","description":"Creator Lab: free courses for the people who gather others. Hosting on the PULSE rhythm, and The Business of Community."},"comments":[]},{"slug":"business-of-community","label":"Business of Community","doc":{"root":{"props":{}},"content":[{"type":"NewWorldHero","props":{"id":"boc-hero-0","eyebrow":"Free course · The Business of Community 101","title":"A full room. *A night that still didn’t pay.*","lead":"A free four-week course for people who already gather others. Learn what a night really costs you, what to charge, who came back, and who to text next week. About an hour a week.","primaryLabel":"Start the course","primaryHref":"/journeys/the-business-of-community-101","secondaryLabel":"Join this month","secondaryHref":"/circles/creator-lab-december-start","proof":"","aside":"","image":"/sites/new-world/photos/backyard-class.webp","alt":"A teacher leads a stretching class on mats and rugs on a sunny backyard patio","badge":"Free for every Space","useEvents":false,"rows":[{"weekday":"Course","mon":"Free","day":"1","title":"The Business of Community 101","body":"Four weeks, five short lessons each.","time":"Self-paced · about an hour a week","where":"Online","spots":"Open","kind":"session","href":"/journeys/the-business-of-community-101"},{"weekday":"Circle","mon":"Free","day":"2","title":"This month’s start","body":"Start with others who began this month.","time":"Starts each month","where":"Online","spots":"Open","kind":"session","href":"/circles/creator-lab-december-start"},{"weekday":"Zoom","mon":"Tue","day":"3","title":"Business Hours","body":"A weekly hour for paid Spaces.","time":"Tuesdays · 10 AM Pacific","where":"Zoom","spots":"Paid Spaces","kind":"session","href":"/spaces/hq/calendar"}],"areas":[],"register":"auto"}},{"type":"NewWorldStats","props":{"id":"boc-facts-1","items":[{"icon":"heart","value":"Free","label":"for every Space","note":"Every lesson, every week"},{"icon":"calendar","value":"4","label":"weeks","note":"One idea each"},{"icon":"check","value":"5","label":"short lessons a week","note":"Story, tools, practice, build, commit"},{"icon":"clock","value":"1","label":"hour a week, about","note":"Spreadsheet and phone are enough"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"boc-pain-2","index":"01","eyebrow":"Sound familiar?","title":"Three ways a good room *wears you out.*","lede":"People love what you run. That part is working. These are the parts nobody taught you.","rows":[{"icon":"tag","title":"A full room that doesn''t cover the night","body":"Rent, gear, snacks, your drive, your hours. The room was packed and you still came home behind."},{"icon":"heart","title":"You carry all of it","body":"Booking, texting, setup, the money, the hard conversations. It all runs through you, and nobody covers when you need a week off."},{"icon":"message","title":"The loudest guest runs the room","body":"Nobody said the rules out loud, so the person with the most opinions made them. Quieter people stop coming back."}],"register":"auto"}},{"type":"NewWorldLongStory","props":{"id":"boc-idea-3","index":"02","eyebrow":"The one idea","title":"Frequency. Not the sound kind. *The how-often kind.*","paragraphs":["Most people who gather others count heads. How many came. How many RSVP''d. How full it looked.","The question isn''t how many came. It''s how many came back. A small room where people return is healthier than a big room you never see again.","Return frequency is the number this course is built around. Every week gives you one more way to keep people coming back without running yourself into the ground."],"register":"auto"}},{"type":"NewWorldQuote","props":{"id":"boc-quote-4","label":"In Daniel’s words","quote":"The question isn''t how many came. It''s *how many came back.*","by":"Daniel Tyack · Founder","register":"auto"}},{"type":"NewWorldStory","props":{"id":"boc-weeks-5","index":"03","eyebrow":"The four weeks","title":"Four weeks. *One idea each.*","paragraphs":["Week 1, The Engine. Structure isn''t the opposite of soul. It''s what keeps the soul from burning out.","Week 2, The Container. A container isn''t what you believe. It''s what you''ve written down, said out loud, and will enforce.","Week 3, The Gathering. Whatever authority you don''t hold, the loudest guest will.","Week 4, The Exchange. Charging is what makes your presence renewable."],"buttonLabel":"Start the course","buttonHref":"/journeys/the-business-of-community-101","secondaryLabel":"Join this month’s start","secondaryHref":"/circles/creator-lab-december-start","image":"/sites/new-world/photos/workshop-table.webp","alt":"Adults and kids making crafts around a long table in a workshop room","quote":"","quoteBy":"","register":"auto"}},{"type":"NewWorldAlways","props":{"id":"boc-leave-6","index":"04","eyebrow":"By the end","title":"Four things *you will know.*","items":["What a gathering costs you","What you charge","Who came back","Who to text next week"],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"boc-who-7","index":"05","eyebrow":"Who it''s for","title":"People who *already gather.*","lede":"Local creators running their thing solo or nearly, with somewhere between ten and a hundred and fifty people.","rows":[{"icon":"heart","title":"Yoga and breathwork teachers","body":"Classes, workshops and retreats you mostly run yourself."},{"icon":"sparkle","title":"Sound healers","body":"Sound baths and circles in studios, homes and parks."},{"icon":"users","title":"Dance and meetup organizers","body":"The regular night people plan their week around."},{"icon":"star","title":"Musicians and open mic hosts","body":"The list, the room, the regulars and the newcomers."},{"icon":"award","title":"Makers","body":"Workshops, classes and craft nights around a table."},{"icon":"pin","title":"House and small venues","body":"A living room, a backyard or a small room that hosts others."}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"boc-each-week-8","index":"06","eyebrow":"How each week works","title":"Five short lessons. *About an hour.*","lede":"It works on a spreadsheet and a phone. The build steps happen inside your own Space.","rows":[{"icon":"eye","title":"The idea","body":"A short story, stopped right at the decision. What would you do?"},{"icon":"check","title":"Four tools","body":"Plain, small tools you can use before your next gathering."},{"icon":"message","title":"Practice out loud","body":"Say the hard sentence before you need it in the room."},{"icon":"calendar","title":"Build it on Frequency","body":"Set it up inside your own Space, so it keeps working after the lesson."},{"icon":"heart","title":"One commitment","body":"Write one commitment down and say it to another person."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"boc-finish-9","index":"07","eyebrow":"Two ways to finish","title":"Attended or *Certified.*","lede":"Pick the one that fits your season.","note":"Certified is a certificate of completion and competency from Frequency. It is not an accredited certification.","rows":[{"title":"Attended","body":"Finish all four weeks. That counts as 10 contact hours."},{"title":"Certified","body":"Submit your Community Book: four one-page sheets plus a 13-week season plan, and do the four builds in your own Space. Review is free through January 31, 2027, then comes with a paid Space."}],"register":"auto"}},{"type":"NewWorldTools","props":{"id":"boc-paid-a","index":"08","eyebrow":"With a paid Space","title":"The course is free. *A paid Space adds a room.*","lede":"The course works on your own. A paid Space adds a regular hour with other Space owners. Plans live on the pricing page.","buttonLabel":"See plans","buttonHref":"/pricing","secondaryLabel":"Ask for a seat","secondaryHref":"/support","note":"Live sessions are on Zoom. Times are Pacific. Check the calendar for the next one.","rows":[{"icon":"clock","title":"Business Hours","body":"Every Tuesday, 10 AM Pacific, on Zoom. Bring one number and one stuck thing."},{"icon":"users","title":"The live pilot cohort","body":"8 to 12 Space owners on Zoom this December. Thursdays Dec 3, 10, 17 and Jan 7, 10:00 to 12:30 Pacific."},{"icon":"check","title":"The course stays free","body":"Every lesson, and this month’s start, is open to every Space."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"boc-faq-b","index":"09","eyebrow":"Questions","title":"Good to *know.*","lede":"Anything else, ask. A real person answers.","rows":[{"icon":"tag","title":"What does it cost?","body":"Nothing. The course and this month’s start are free for every Space. Certified review is free through January 31, 2027, then comes with a paid Space."},{"icon":"clock","title":"How much time each week?","body":"About an hour: five short lessons. Do them in one sitting or spread them out."},{"icon":"pin","title":"Do I need a Space?","body":"The build steps happen inside your own Space, and Certified needs the four builds done there. The rest works on a spreadsheet and a phone."},{"icon":"award","title":"Is it accredited?","body":"No. Certified is a certificate of completion and competency from Frequency, not an accredited certification."},{"icon":"calendar","title":"What if I miss a week?","body":"Pick it up where you left off. The lessons wait for you."},{"icon":"eye","title":"Is it live or self-paced?","body":"Self-paced. Paid Spaces can add a live hour each week and a seat in the live pilot cohort on Zoom."},{"icon":"message","title":"What is Business Hours?","body":"A weekly hour on Zoom for paid Spaces, Tuesdays at 10 AM Pacific. Bring one number and one stuck thing."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"boc-closer-c","aside":"Free. Four weeks. About an hour each.","title":"Keep the room. *Keep yourself.*","primaryLabel":"Start the course","primaryHref":"/journeys/the-business-of-community-101","secondaryLabel":"Ask a question","secondaryHref":"/spaces/hq/help","note":"Want company? This month’s start is free too.","register":"auto"}}]},"seo":{"title":"The Business of Community 101 · Frequency","description":"A free four-week course for people who already gather others. Know what a night costs you, what to charge, who came back, and who to text next week."},"comments":[]},{"slug":"help","label":"Help desk","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-help-head-22","index":"","eyebrow":"Help desk","title":"Ask. *A person answers.*","lede":"Open a help ticket, browse the help center, or ask the community. Every ticket is read by a real person on the Frequency team.","register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-help-rows-23","costLabel":"Cost","whenLabel":"Best for","buttonLabel":"Open a help ticket","buttonHref":"/support","secondaryLabel":"Common questions","secondaryHref":"#faq","rows":[{"icon":"message","tags":"Help desk","name":"Open a help ticket","body":"Tell us what happened. Follow every reply from your tickets.","price":"Free","when":"Your account, billing, bugs","image":"/sites/new-world/photos/cafe-table.webp","alt":"Three people talking at a small table in a cafe","buttonLabel":"Open a ticket","href":"/support"},{"icon":"check","tags":"Help center","name":"Browse the help center","body":"Plain answers on Circles, events, Spaces, The Quest and membership.","price":"Free","when":"How-to questions","image":"/sites/new-world/photos/garden-picnic.webp","alt":"People gathered on rugs and cushions in a leafy backyard garden","buttonLabel":"Open the help center","href":"/help"},{"icon":"users","tags":"Forum","name":"Ask the community","body":"Post a question or an idea. Members, hosts and the team answer.","price":"Free","when":"Ideas and how others do it","image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck","buttonLabel":"Go to the forum","href":"/spaces/hq/community"},{"icon":"heart","tags":"Safety","name":"Report a safety concern","body":"Reporting, blocking and how moderation works. In an emergency, call emergency services first.","price":"Free","when":"Anything that feels unsafe","image":"/sites/new-world/photos/fire-circle.webp","alt":"People sitting quietly around a fire pit in the evening","buttonLabel":"Safety and reporting","href":"/help/safety"}],"register":"auto"}},{"type":"NewWorldPosts","props":{"id":"fh-help-center-24","index":"01","eyebrow":"Help center","title":"Find it *fast.*","lede":"Seven topics, written in plain words.","buttonLabel":"Open the help center","buttonHref":"/help","rows":[{"kind":"Start here","title":"Getting started: what Frequency is and how to find your people","meta":"","href":"/help/getting-started"},{"kind":"Groups","title":"Circles and events: how gatherings work","meta":"","href":"/help/groups"},{"kind":"Hosting","title":"Leading a Circle: start one, run the first night, keep it going","meta":"","href":"/help/leading"},{"kind":"Spaces","title":"Running a Space: the tools a Space gives you","meta":"","href":"/help/spaces"},{"kind":"The Quest","title":"Zaps, Gems, ranks and rewards","meta":"","href":"/help/the-quest"},{"kind":"Membership","title":"What''s free and what Crew adds","meta":"","href":"/help/membership"},{"kind":"Safety","title":"Reporting, blocking and how moderation works","meta":"","href":"/help/safety"}],"register":"auto"}},{"type":"NewWorldFaq","props":{"id":"fh-help-faq-25","index":"02","eyebrow":"Questions","title":"Good to *know.*","lede":"Still stuck? Open a ticket or email us.","phone":"","email":"hello@frequencylocal.com","hours":"","areasLabel":"","areas":[],"rows":[{"question":"How do I open a help ticket?","answer":"Go to Help and support, describe what happened, and send it. You can follow every reply from your tickets on the same page."},{"question":"Something feels unsafe. What do I do?","answer":"Use Report on the post, profile or event, or open a ticket marked safety. If anyone is in immediate danger, call emergency services first."},{"question":"I have a billing question.","answer":"Open a ticket and choose billing. Include the email on your account so we can find it quickly."},{"question":"How do I start a Space for my business or group?","answer":"Read Running a Space in the help center, then create one from the Spaces page. The help desk can walk you through it."},{"question":"Can I suggest a feature?","answer":"Yes, please. Post it in the community forum so others can add to it, or open a ticket if it is about your own account."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-help-26","aside":"Generous structure. Real care. On time.","title":"Still stuck? *Ask us.*","primaryLabel":"Open a help ticket","primaryHref":"/support","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","note":"","register":"auto"}}]},"seo":{"title":"Help desk · Frequency","description":"Open a help ticket, browse the help center, or ask the community."},"comments":[]},{"slug":"about","label":"About","doc":{"root":{"props":{}},"content":[{"type":"NewWorldAboutHero","props":{"id":"fh-about-hero-27","eyebrow":"Our story · Frequency","title":"Build circles, *not walls.*","lead":"Frequency is a community collective that spreads town by town through local hosts. This Space is where the team shares the programs, the training, the answers and the conversation in the open.","chips":[{"icon":"check","text":"Free to start"},{"icon":"users","text":"Run with its members"},{"icon":"heart","text":"Care designed in"}],"primaryLabel":"Explore programs","primaryHref":"/spaces/hq/programs","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","image":"/sites/new-world/photos/circle-sunrise.webp","alt":"A wide circle of people seated on a plaza at sunrise","name":"Daniel Tyack","role":"Founder","register":"auto"}},{"type":"NewWorldLongStory","props":{"id":"fh-about-roots-28","index":"01","eyebrow":"Where this comes from","title":"Old practices, *plain words.*","paragraphs":["Sitting in a circle and taking turns to speak is one of the oldest ways people have gathered. We did not invent it. We gave it a rhythm, PULSE, that a new host can learn in a week and a returning guest can trust.","Our host training draws on a few sources worth reading in full. The Way of Council, as taught by Jack Zimmerman and Virginia Coyle, gives us the talking piece and its intentions. Parker Palmer and the Center for Courage and Renewal give us touchstones for trustworthy space, like no fixing and honest, open questions. Priya Parker gives us generous authority: a host who protects, connects and equalizes the room. SAMHSA gives us the six principles of a trauma-informed approach.","Everything is written in plain words, because a host should be able to read an agreement aloud without explaining it."],"register":"auto"}},{"type":"NewWorldQuote","props":{"id":"fh-about-quote-29","label":"In Daniel’s words","quote":"The structure exists to serve the circle. The circle *governs the structure.*","by":"Daniel Tyack · Founder","register":"auto"}},{"type":"NewWorldTeam","props":{"id":"fh-about-team-2a","index":"02","eyebrow":"The team","title":"Who *runs this.*","lede":"","note":"Trained hosts join this list as they become mentors.","rows":[{"name":"Daniel Tyack","role":"Founder · The Janitor","image":"/brand/frequency/photos/daniel-tyack.jpg","alt":"Daniel Tyack smiling"}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-about-2b","aside":"Generous structure. Real care. On time.","title":"Pick a door. *Come in.*","primaryLabel":"Ask the community","primaryHref":"/spaces/hq/community","secondaryLabel":"Get help","secondaryHref":"/support","note":"","register":"auto"}}]},"seo":{"title":"About · Frequency","description":"Frequency is a community collective. Build circles, not walls."},"comments":[]}]},"scheduled":null,"versions":[{"id":"1","createdAt":"2026-11-18T01:59:15.786Z","author":"Frequency","snapshot":{"theme":"NewWorld","brand":{"logo":"/brand/frequency/logo/frequency-icon-round.png","accent":"#1AA7C0"},"chrome":{"name":"Frequency","tagline":"Gather like it matters.","cta":{"label":"Get help","href":"/support"}},"pages":[{"slug":"home","label":"Home","doc":{"root":{"props":{}},"content":[{"type":"NewWorldHero","props":{"id":"fh-home-hero-18","eyebrow":"Frequency · Programs, training and help","title":"Gather like it *matters.*","lead":"The home base for everyone building Frequency. Find our programs, learn to host on the PULSE rhythm, get help from a real person, and ask the community anything. Start wherever you are.","primaryLabel":"Explore programs","primaryHref":"/spaces/hq/programs","secondaryLabel":"Get help","secondaryHref":"/spaces/hq/help","proof":"Run by the Frequency team, for members, hosts and Spaces.","aside":"We build circles, not walls.","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","badge":"Open to everyone","useEvents":true,"rows":[{"weekday":"Help","mon":"Desk","day":"1","title":"Open a help ticket","body":"A real person reads every ticket.","time":"Any time","where":"Online","spots":"Open","kind":"session","href":"/support"},{"weekday":"Course","mon":"Free","day":"2","title":"The Business of Community 101","body":"Run your community like it’s going to last. Four weeks, free for every Space.","time":"4 weeks · about an hour each","where":"Online","spots":"Open","kind":"session","href":"/journeys/the-business-of-community-101"},{"weekday":"Course","mon":"Free","day":"3","title":"Host Foundations","body":"Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.","time":"Self-paced · 4 parts","where":"Online","spots":"Open","kind":"session","href":"/journeys/host-foundations"}],"register":"auto"}},{"type":"NewWorldStats","props":{"id":"fh-home-stats-19","items":[{"icon":"heart","value":"4","label":"Pillars","note":"Mind, Body, Spirit, Expression"},{"icon":"users","value":"5","label":"beats in every circle","note":"Presence, Unite, Lead, Settle, Exhale"},{"icon":"calendar","value":"4","label":"host courses","note":"Three free online, one in person"},{"icon":"check","value":"1","label":"help desk","note":"A real person answers"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-home-doors-1a","index":"01","eyebrow":"Inside","title":"Five *doors.*","lede":"Everything the Frequency team runs for members, hosts and Spaces.","rows":[{"icon":"award","title":"Programs","body":"The Quest, Circles, events and host training: the structured ways to take part."},{"icon":"heart","title":"Host training","body":"Free courses on the PULSE rhythm, care and consent, and the three circle formats."},{"icon":"check","title":"Help desk","body":"Open a ticket, browse the help center, or report something that feels off."},{"icon":"sparkle","title":"Creator Lab","body":"Business and leadership for the people who gather others. Starts with The Business of Community 101."},{"icon":"users","title":"Community forum","body":"Ask a question, share what worked, suggest a feature. Hosts and the team read it."}],"register":"auto"}},{"type":"NewWorldStory","props":{"id":"fh-home-story-1b","index":"02","eyebrow":"A community collective","title":"Built by *its members.*","paragraphs":["Frequency is a community collective, not just an app. The software helps people find each other and helps local hosts and businesses run their rooms. The point is the room.","We grow town by town, one circle at a time. Every one of those circles needs someone who arrives early, sets the chairs, starts on time and makes the new person feel expected.","This Space is where that work is shared in the open: the programs, the training, the answers and the conversation."],"buttonLabel":"Our story","buttonHref":"/spaces/hq/about","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","quote":"The structure exists to serve the circle.","quoteBy":"Daniel Tyack · Founder","register":"auto"}},{"type":"SpacePractices","props":{"id":"fh-home-journeys-1c","eyebrow":"Learn here","heading":"Courses to start","practicesHeading":"Practices","journeysHeading":"Courses","only":""}},{"type":"NewWorldProcess","props":{"id":"fh-home-path-1d","index":"03","eyebrow":"Host training","title":"From guest to *host.*","lede":"","rows":[{"icon":"calendar","title":"Learn","body":"Take Host Foundations, free and self-paced. Four short weeks on the PULSE rhythm."},{"icon":"heart","title":"Learn to care","body":"Take Safe and Well Held: agreements, consent and what to do when something comes up."},{"icon":"users","title":"Co-host","body":"Run two circles beside a trained host. Lead one beat, then two, then the whole night."},{"icon":"award","title":"Host","body":"Open your own circle with a mentor on call, then join the monthly Host Circle."}],"register":"auto"}},{"type":"NewWorldGallery","props":{"id":"fh-home-gallery-1e","index":"04","eyebrow":"Real circles","title":"Rooms people *come back to.*","lede":"Photos from Frequency gatherings.","images":[{"image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide"},{"image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck"},{"image":"/brand/frequency/photos/day-parachute-play.jpg","alt":"People holding a rainbow parachute on a clifftop lawn"},{"image":"/brand/frequency/photos/gathering-14.jpg","alt":"A circle on mats around a gong at the water"},{"image":"/brand/frequency/photos/gathering-13.jpg","alt":"A group moving together on the beach at golden hour"}],"register":"auto"}},{"type":"NewWorldFaq","props":{"id":"fh-home-faq-1f","index":"05","eyebrow":"Questions","title":"Good to *know.*","lede":"Anything else, ask. A real person answers.","phone":"","email":"hello@frequencylocal.com","hours":"","areasLabel":"","areas":[],"rows":[{"question":"What is this Space?","answer":"The Frequency team''s own Space: our programs, host training, Creator Lab, the help desk and a community forum, in one place. Follow it to hear what''s new."},{"question":"How do I get help with my account?","answer":"Open a help ticket from the help desk. A real person reads every one, and you can follow the reply from your tickets."},{"question":"Do I need experience to host?","answer":"No. Most Frequency hosts started as guests. Host Foundations and the apprenticeship take you from your first seat in the circle to running your own."},{"question":"Can my organization train its own hosts here?","answer":"Yes. The courses and the PULSE rhythm are built so partner organizations and volunteers can use them for their own in-person and online groups."},{"question":"Where do I ask other members a question?","answer":"In the community forum. Post a question, share what worked, or say hello. Hosts and the team read it too."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-home-1g","aside":"Generous structure. Real care. On time.","title":"Pick a door. *Come in.*","primaryLabel":"Ask the community","primaryHref":"/spaces/hq/community","secondaryLabel":"Get help","secondaryHref":"/support","note":"","register":"auto"}}]},"seo":{"title":"Frequency","description":"Frequency: programs, free host training, Creator Lab, a help desk and a community forum."},"comments":[]},{"slug":"programs","label":"Programs","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-programs-head-1h","index":"","eyebrow":"Frequency Programs","title":"Show up. *Come back.*","lede":"Frequency Programs are the structured ways to take part: The Quest, Circles, local events and host training. Start with one.","register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-programs-rows-1i","costLabel":"For","whenLabel":"Rhythm","buttonLabel":"Start","buttonHref":"/circles","secondaryLabel":"Questions","secondaryHref":"/spaces/hq/help","rows":[{"icon":"award","tags":"Program","name":"The Quest","body":"Daily practices and Journeys you take with your Circle, across the four Pillars. Show up, earn Zaps and Gems, and climb the season.","price":"Every member","when":"Daily","image":"/brand/frequency/photos/gathering-13.jpg","alt":"A group moving together on the beach at golden hour","buttonLabel":"How The Quest works","href":"/help/the-quest"},{"icon":"users","tags":"Program","name":"Circles","body":"Small groups of 12 to 18 people who meet at the same time in the same place, on the PULSE rhythm.","price":"Every member","when":"Weekly or every other week","image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide","buttonLabel":"Find a Circle","href":"/circles"},{"icon":"calendar","tags":"Program","name":"What''s happening","body":"Local events from Circles and Spaces near you. RSVP, add it to your calendar, bring someone.","price":"Everyone","when":"Any week","image":"/brand/frequency/photos/day-parachute-play.jpg","alt":"People holding a rainbow parachute on a clifftop lawn","buttonLabel":"See what''s happening","href":"/events"},{"icon":"sparkle","tags":"Program","name":"Creator Lab","body":"Business and leadership for community creators. The Business of Community 101 is free for every Space; paid Spaces add Business Hours on Zoom.","price":"Every Space","when":"One week at a time","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","buttonLabel":"Open Creator Lab","href":"/spaces/hq/creator-lab"},{"icon":"heart","tags":"Program","name":"Host training","body":"Free courses on the PULSE rhythm, care and consent, and the three circle formats, then a co-host apprenticeship.","price":"Hosts and future hosts","when":"Self-paced","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"A large circle of people seated on the grass by the ocean, eyes closed","buttonLabel":"Start host training","href":"/spaces/hq/creator-lab"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-programs-pillars-1j","index":"01","eyebrow":"The Quest","title":"Four *Pillars.*","lede":"Every practice and Journey sits under one Pillar, so you build the same strengths all year in different forms.","rows":[{"icon":"sparkle","title":"Mind","body":"Calm down fast, focus, and think clearly. Practices like breathing, journaling and less scrolling."},{"icon":"heart","title":"Body","body":"Move, rest, eat and sleep like you mean it. Walks, stretching, cold water, early nights."},{"icon":"users","title":"Spirit","body":"Meaning, gratitude and time with people. Stillness, service and showing up for each other."},{"icon":"award","title":"Expression","body":"Make something and share it. The weekly Expression Challenge, alone or with your Circle."}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"fh-programs-quest-1k","index":"02","eyebrow":"How The Quest works","title":"Small things, *every day.*","lede":"","rows":[{"icon":"calendar","title":"Pick a Journey","body":"Choose one under a Pillar. Each has a few minutes of practice a day."},{"icon":"check","title":"Practice daily","body":"Log it when you do it. Streaks build, and misses are part of it."},{"icon":"users","title":"Bring your Circle","body":"Take a Journey with your Circle and show up for each other in person."},{"icon":"award","title":"Earn as you go","body":"Zaps and Gems for showing up, a Pillar Trophy when you finish a Journey."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-programs-1l","aside":"Generous structure. Real care. On time.","title":"Start with *one.*","primaryLabel":"Find a Circle","primaryHref":"/circles","secondaryLabel":"See what''s happening","secondaryHref":"/events","note":"","register":"auto"}}]},"seo":{"title":"Programs · Frequency","description":"Frequency Programs: The Quest, Circles, local events and host training."},"comments":[]},{"slug":"creator-lab","label":"Creator Lab","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-lib-head-2c","index":"","eyebrow":"Creator Lab","title":"Courses for the people who *gather others.*","lede":"Free courses in two tracks: hosting the room, and running the community behind it. Start anywhere. Every course ends with you doing it for real.","register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-lib-tracks-2d","index":"01","eyebrow":"The library","title":"Two *tracks.*","lede":"Each course is free. Paid Spaces add a weekly room on Zoom.","rows":[{"icon":"heart","title":"Hosting","body":"The PULSE rhythm, care and consent, the three circle formats, and an apprenticeship beside a trained host."},{"icon":"sparkle","title":"Business and leadership","body":"The Business of Community: what a gathering costs you, what to charge, who came back, and who to text next week."}],"register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-lib-rows-2e","costLabel":"Cost","whenLabel":"Length","buttonLabel":"Start a course","buttonHref":"/spaces/hq/business-of-community","secondaryLabel":"Questions","secondaryHref":"/spaces/hq/help","rows":[{"icon":"calendar","tags":"Business · 4 weeks","name":"The Business of Community 101","body":"Four weeks: The Engine, The Container, The Gathering, The Exchange. Five short lessons a week, about an hour, ending in one commitment.","price":"Free","when":"4 weeks","image":"/brand/frequency/photos/gathering-03.jpg","alt":"People gathered on rugs and cushions in a leafy garden","buttonLabel":"See the course","href":"/spaces/hq/business-of-community"},{"icon":"users","tags":"Business · monthly start","name":"This month’s start","body":"Everyone who starts this month moves through it together. A thread to share what you tried, and someone noticing when you don’t.","price":"Free","when":"Starts each month","image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck","buttonLabel":"Join this month","href":"/circles/creator-lab-december-start"},{"icon":"message","tags":"Business · Zoom","name":"Business Hours","body":"Same hour every week. Bring one number and one stuck thing. Commitments read back, one hot seat, a work block, and a new if-then.","price":"Paid Spaces","when":"Tuesdays · 10 AM Pacific","image":"/sites/new-world/photos/cafe-table.webp","alt":"Three people talking at a small table in a cafe","buttonLabel":"See the calendar","href":"/spaces/hq/calendar"},{"icon":"award","tags":"Business · Zoom","name":"Live cohort","body":"Eight to twelve Space owners, four weekly 2.5-hour workshops, ending in the Certified capstone. The pilot runs this December.","price":"Paid Spaces","when":"Four weeks","image":"/brand/frequency/photos/gathering-04.jpg","alt":"A circle seated on a lawn with arms stretched wide","buttonLabel":"Ask for a seat","href":"/support"},{"icon":"calendar","tags":"Hosting · Online","name":"Host Foundations","body":"Four short weeks on the craft every Frequency host shares: why we gather, the PULSE rhythm, setting the room, and running your first circle.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/day-meditation-circle.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/host-foundations"},{"icon":"heart","tags":"Hosting · Online","name":"Safe and Well Held","body":"Agreements, consent and care: how to keep a room safe enough to be honest, and what to do when something comes up.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/gathering-12.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/safe-and-well-held"},{"icon":"users","tags":"Hosting · Online","name":"The Three Circle Formats","body":"Open, Community and Focus Circles: what each one is for, what the host does, and how to choose.","price":"Free","when":"4 parts","image":"/brand/frequency/photos/gathering-03.jpg","alt":"","buttonLabel":"Start the course","href":"/journeys/circle-formats"},{"icon":"award","tags":"Hosting · In person","name":"Co-host Apprenticeship","body":"Learn by doing: shadow a trained host, co-lead two circles, then host your own with a mentor on call.","price":"Ask us","when":"Three circles","image":"/brand/frequency/photos/gathering-04.jpg","alt":"","buttonLabel":"Ask about a mentor","href":"/journeys/co-host-apprenticeship"}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"fh-pulse-beats-1p","index":"02","eyebrow":"The PULSE rhythm · for everyone","title":"What each beat *is.*","lede":"","rows":[{"icon":"heart","title":"P · Presence","body":"Arrive. A few slow breaths, feet on the floor, phones away. The host sets the tone by going first."},{"icon":"users","title":"U · Unite","body":"A check-in round. Each person says how they''re arriving, and everyone else listens without replying."},{"icon":"award","title":"L · Lead","body":"Tonight''s practice: a teaching, a movement, a conversation or a skill. The part that changes from week to week."},{"icon":"check","title":"S · Settle","body":"Quiet integration. Rest, journal or sit with what came up before anyone has to talk about it."},{"icon":"message","title":"E · Exhale","body":"Close together. One word or one line each, a thank you, and a clear end."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"fh-pulse-host-1q","index":"03","eyebrow":"The PULSE rhythm · for the host","title":"What you *do.*","lede":"A 90-minute night, beat by beat.","note":"Shorter night? Trim Lead first. Never skip Exhale.","rows":[{"title":"Presence · 10 min","body":"Start on time. Welcome people by name. Name the purpose of tonight in one sentence."},{"title":"Unite · 20 min","body":"Read the agreements. Ask one question everyone can answer. Keep it lean so everyone gets a turn."},{"title":"Lead · 35 min","body":"Give clear steps, an invitation and an opt-out. Watch the room more than your notes."},{"title":"Settle · 15 min","body":"Lower the pace. Offer a simple prompt. Let silence do some of the work."},{"title":"Exhale · 10 min","body":"End on time. Say what happens next and how people can reach you."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-training-formats-1r","index":"04","eyebrow":"One rhythm","title":"Three *formats.*","lede":"Every circle runs on PULSE. The format decides how much you teach and how big the room gets.","rows":[{"icon":"users","title":"Open Circle · 12 to 18 people","body":"The host keeps the room, with no teaching agenda. People come to be heard and to hear each other. You open and close, keep the agreements and the time, and pass the turn. You speak least."},{"icon":"heart","title":"Community Circle · 12 to 18 people","body":"A hosted circle around one shared theme: moon circles, men''s and women''s circles, grief, new parents, sharing circles. You choose the theme and the question for the round, and keep the circle on it."},{"icon":"award","title":"Focus Circle · Up to 50 people","body":"The host teaches a modality: breathwork, sound, movement, a skill. The PULSE rhythm wraps the teaching so the room still feels like a circle. You teach in the Lead beat, and the four beats around it keep it personal and safe."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"fh-training-agreements-1s","index":"05","eyebrow":"Read at every circle","title":"Six *agreements.*","lede":"","rows":[{"icon":"check","title":"Every practice is an invitation","body":"Join in, go gently, watch, or pass. No one needs a reason."},{"icon":"heart","title":"What is shared stays here","body":"Take the lessons home. Leave the stories and the names in the room."},{"icon":"users","title":"Speak for yourself","body":"Use I. Speak from your own life, not about anyone else''s."},{"icon":"message","title":"No fixing","body":"Listen without advising, correcting or rescuing. Ask an honest question, or simply say thank you."},{"icon":"calendar","title":"Start and end on time","body":"A clear start and a clear end are a kindness. People can plan around you."},{"icon":"award","title":"Ask before touch","body":"No touch without a clear yes, every time. Nothing sexual happens in a circle."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"fh-training-care-1t","index":"06","eyebrow":"When something comes up","title":"Safe enough *to be honest.*","lede":"Our training follows the six principles of a trauma-informed approach: safety, trust and transparency, peer support, collaboration, choice and voice, and culture and context.","note":"A Frequency circle is practice and community, not therapy or crisis care. In the US, call or text 988 for the Suicide and Crisis Lifeline. If anyone is in immediate danger, call emergency services.","rows":[{"title":"Strong feelings","body":"Slow down. Let the person finish, thank them, and offer a breath for the whole circle. Tears aren''t an emergency."},{"title":"A disclosure","body":"Thank them, don''t press for details in the circle, and speak privately afterwards. Share the local crisis line."},{"title":"One voice filling the room","body":"Use the talking piece. Set a time per share before the round starts. Invite someone who hasn’t spoken yet."},{"title":"After a hard night","body":"Debrief with your co-host or mentor within a day. Hosting is a team practice."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-creator-lab-2f","aside":"Generous structure. Real care. On time.","title":"Start with *one course.*","primaryLabel":"The Business of Community","primaryHref":"/spaces/hq/business-of-community","secondaryLabel":"Start Host Foundations","secondaryHref":"/journeys/host-foundations","note":"","register":"auto"}}]},"seo":{"title":"Creator Lab · Frequency","description":"Creator Lab: free courses for the people who gather others. Hosting on the PULSE rhythm, and The Business of Community."},"comments":[]},{"slug":"business-of-community","label":"Business of Community","doc":{"root":{"props":{}},"content":[{"type":"NewWorldHero","props":{"id":"boc-hero-0","eyebrow":"Free course · The Business of Community 101","title":"A full room. *A night that still didn’t pay.*","lead":"A free four-week course for people who already gather others. Learn what a night really costs you, what to charge, who came back, and who to text next week. About an hour a week.","primaryLabel":"Start the course","primaryHref":"/journeys/the-business-of-community-101","secondaryLabel":"Join this month","secondaryHref":"/circles/creator-lab-december-start","proof":"","aside":"","image":"/sites/new-world/photos/backyard-class.webp","alt":"A teacher leads a stretching class on mats and rugs on a sunny backyard patio","badge":"Free for every Space","useEvents":false,"rows":[{"weekday":"Course","mon":"Free","day":"1","title":"The Business of Community 101","body":"Four weeks, five short lessons each.","time":"Self-paced · about an hour a week","where":"Online","spots":"Open","kind":"session","href":"/journeys/the-business-of-community-101"},{"weekday":"Circle","mon":"Free","day":"2","title":"This month’s start","body":"Start with others who began this month.","time":"Starts each month","where":"Online","spots":"Open","kind":"session","href":"/circles/creator-lab-december-start"},{"weekday":"Zoom","mon":"Tue","day":"3","title":"Business Hours","body":"A weekly hour for paid Spaces.","time":"Tuesdays · 10 AM Pacific","where":"Zoom","spots":"Paid Spaces","kind":"session","href":"/spaces/hq/calendar"}],"areas":[],"register":"auto"}},{"type":"NewWorldStats","props":{"id":"boc-facts-1","items":[{"icon":"heart","value":"Free","label":"for every Space","note":"Every lesson, every week"},{"icon":"calendar","value":"4","label":"weeks","note":"One idea each"},{"icon":"check","value":"5","label":"short lessons a week","note":"Story, tools, practice, build, commit"},{"icon":"clock","value":"1","label":"hour a week, about","note":"Spreadsheet and phone are enough"}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"boc-pain-2","index":"01","eyebrow":"Sound familiar?","title":"Three ways a good room *wears you out.*","lede":"People love what you run. That part is working. These are the parts nobody taught you.","rows":[{"icon":"tag","title":"A full room that doesn''t cover the night","body":"Rent, gear, snacks, your drive, your hours. The room was packed and you still came home behind."},{"icon":"heart","title":"You carry all of it","body":"Booking, texting, setup, the money, the hard conversations. It all runs through you, and nobody covers when you need a week off."},{"icon":"message","title":"The loudest guest runs the room","body":"Nobody said the rules out loud, so the person with the most opinions made them. Quieter people stop coming back."}],"register":"auto"}},{"type":"NewWorldLongStory","props":{"id":"boc-idea-3","index":"02","eyebrow":"The one idea","title":"Frequency. Not the sound kind. *The how-often kind.*","paragraphs":["Most people who gather others count heads. How many came. How many RSVP''d. How full it looked.","The question isn''t how many came. It''s how many came back. A small room where people return is healthier than a big room you never see again.","Return frequency is the number this course is built around. Every week gives you one more way to keep people coming back without running yourself into the ground."],"register":"auto"}},{"type":"NewWorldQuote","props":{"id":"boc-quote-4","label":"In Daniel’s words","quote":"The question isn''t how many came. It''s *how many came back.*","by":"Daniel Tyack · Founder","register":"auto"}},{"type":"NewWorldStory","props":{"id":"boc-weeks-5","index":"03","eyebrow":"The four weeks","title":"Four weeks. *One idea each.*","paragraphs":["Week 1, The Engine. Structure isn''t the opposite of soul. It''s what keeps the soul from burning out.","Week 2, The Container. A container isn''t what you believe. It''s what you''ve written down, said out loud, and will enforce.","Week 3, The Gathering. Whatever authority you don''t hold, the loudest guest will.","Week 4, The Exchange. Charging is what makes your presence renewable."],"buttonLabel":"Start the course","buttonHref":"/journeys/the-business-of-community-101","secondaryLabel":"Join this month’s start","secondaryHref":"/circles/creator-lab-december-start","image":"/sites/new-world/photos/workshop-table.webp","alt":"Adults and kids making crafts around a long table in a workshop room","quote":"","quoteBy":"","register":"auto"}},{"type":"NewWorldAlways","props":{"id":"boc-leave-6","index":"04","eyebrow":"By the end","title":"Four things *you will know.*","items":["What a gathering costs you","What you charge","Who came back","Who to text next week"],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"boc-who-7","index":"05","eyebrow":"Who it''s for","title":"People who *already gather.*","lede":"Local creators running their thing solo or nearly, with somewhere between ten and a hundred and fifty people.","rows":[{"icon":"heart","title":"Yoga and breathwork teachers","body":"Classes, workshops and retreats you mostly run yourself."},{"icon":"sparkle","title":"Sound healers","body":"Sound baths and circles in studios, homes and parks."},{"icon":"users","title":"Dance and meetup organizers","body":"The regular night people plan their week around."},{"icon":"star","title":"Musicians and open mic hosts","body":"The list, the room, the regulars and the newcomers."},{"icon":"award","title":"Makers","body":"Workshops, classes and craft nights around a table."},{"icon":"pin","title":"House and small venues","body":"A living room, a backyard or a small room that hosts others."}],"register":"auto"}},{"type":"NewWorldProcess","props":{"id":"boc-each-week-8","index":"06","eyebrow":"How each week works","title":"Five short lessons. *About an hour.*","lede":"It works on a spreadsheet and a phone. The build steps happen inside your own Space.","rows":[{"icon":"eye","title":"The idea","body":"A short story, stopped right at the decision. What would you do?"},{"icon":"check","title":"Four tools","body":"Plain, small tools you can use before your next gathering."},{"icon":"message","title":"Practice out loud","body":"Say the hard sentence before you need it in the room."},{"icon":"calendar","title":"Build it on Frequency","body":"Set it up inside your own Space, so it keeps working after the lesson."},{"icon":"heart","title":"One commitment","body":"Write one commitment down and say it to another person."}],"register":"auto"}},{"type":"NewWorldFirstVisit","props":{"id":"boc-finish-9","index":"07","eyebrow":"Two ways to finish","title":"Attended or *Certified.*","lede":"Pick the one that fits your season.","note":"Certified is a certificate of completion and competency from Frequency. It is not an accredited certification.","rows":[{"title":"Attended","body":"Finish all four weeks. That counts as 10 contact hours."},{"title":"Certified","body":"Submit your Community Book: four one-page sheets plus a 13-week season plan, and do the four builds in your own Space. Review is free through January 31, 2027, then comes with a paid Space."}],"register":"auto"}},{"type":"NewWorldTools","props":{"id":"boc-paid-a","index":"08","eyebrow":"With a paid Space","title":"The course is free. *A paid Space adds a room.*","lede":"The course works on your own. A paid Space adds a regular hour with other Space owners. Plans live on the pricing page.","buttonLabel":"See plans","buttonHref":"/pricing","secondaryLabel":"Ask for a seat","secondaryHref":"/support","note":"Live sessions are on Zoom. Times are Pacific. Check the calendar for the next one.","rows":[{"icon":"clock","title":"Business Hours","body":"Every Tuesday, 10 AM Pacific, on Zoom. Bring one number and one stuck thing."},{"icon":"users","title":"The live pilot cohort","body":"8 to 12 Space owners on Zoom this December. Thursdays Dec 3, 10, 17 and Jan 7, 10:00 to 12:30 Pacific."},{"icon":"check","title":"The course stays free","body":"Every lesson, and this month’s start, is open to every Space."}],"register":"auto"}},{"type":"NewWorldPromises","props":{"id":"boc-faq-b","index":"09","eyebrow":"Questions","title":"Good to *know.*","lede":"Anything else, ask. A real person answers.","rows":[{"icon":"tag","title":"What does it cost?","body":"Nothing. The course and this month’s start are free for every Space. Certified review is free through January 31, 2027, then comes with a paid Space."},{"icon":"clock","title":"How much time each week?","body":"About an hour: five short lessons. Do them in one sitting or spread them out."},{"icon":"pin","title":"Do I need a Space?","body":"The build steps happen inside your own Space, and Certified needs the four builds done there. The rest works on a spreadsheet and a phone."},{"icon":"award","title":"Is it accredited?","body":"No. Certified is a certificate of completion and competency from Frequency, not an accredited certification."},{"icon":"calendar","title":"What if I miss a week?","body":"Pick it up where you left off. The lessons wait for you."},{"icon":"eye","title":"Is it live or self-paced?","body":"Self-paced. Paid Spaces can add a live hour each week and a seat in the live pilot cohort on Zoom."},{"icon":"message","title":"What is Business Hours?","body":"A weekly hour on Zoom for paid Spaces, Tuesdays at 10 AM Pacific. Bring one number and one stuck thing."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"boc-closer-c","aside":"Free. Four weeks. About an hour each.","title":"Keep the room. *Keep yourself.*","primaryLabel":"Start the course","primaryHref":"/journeys/the-business-of-community-101","secondaryLabel":"Ask a question","secondaryHref":"/spaces/hq/help","note":"Want company? This month’s start is free too.","register":"auto"}}]},"seo":{"title":"The Business of Community 101 · Frequency","description":"A free four-week course for people who already gather others. Know what a night costs you, what to charge, who came back, and who to text next week."},"comments":[]},{"slug":"help","label":"Help desk","doc":{"root":{"props":{}},"content":[{"type":"NewWorldPageHead","props":{"id":"fh-help-head-22","index":"","eyebrow":"Help desk","title":"Ask. *A person answers.*","lede":"Open a help ticket, browse the help center, or ask the community. Every ticket is read by a real person on the Frequency team.","register":"auto"}},{"type":"NewWorldWayRows","props":{"id":"fh-help-rows-23","costLabel":"Cost","whenLabel":"Best for","buttonLabel":"Open a help ticket","buttonHref":"/support","secondaryLabel":"Common questions","secondaryHref":"#faq","rows":[{"icon":"message","tags":"Help desk","name":"Open a help ticket","body":"Tell us what happened. Follow every reply from your tickets.","price":"Free","when":"Your account, billing, bugs","image":"/sites/new-world/photos/cafe-table.webp","alt":"Three people talking at a small table in a cafe","buttonLabel":"Open a ticket","href":"/support"},{"icon":"check","tags":"Help center","name":"Browse the help center","body":"Plain answers on Circles, events, Spaces, The Quest and membership.","price":"Free","when":"How-to questions","image":"/sites/new-world/photos/garden-picnic.webp","alt":"People gathered on rugs and cushions in a leafy backyard garden","buttonLabel":"Open the help center","href":"/help"},{"icon":"users","tags":"Forum","name":"Ask the community","body":"Post a question or an idea. Members, hosts and the team answer.","price":"Free","when":"Ideas and how others do it","image":"/brand/frequency/photos/gathering-12.jpg","alt":"A tight group hugging and laughing on a seaside deck","buttonLabel":"Go to the forum","href":"/spaces/hq/community"},{"icon":"heart","tags":"Safety","name":"Report a safety concern","body":"Reporting, blocking and how moderation works. In an emergency, call emergency services first.","price":"Free","when":"Anything that feels unsafe","image":"/sites/new-world/photos/fire-circle.webp","alt":"People sitting quietly around a fire pit in the evening","buttonLabel":"Safety and reporting","href":"/help/safety"}],"register":"auto"}},{"type":"NewWorldPosts","props":{"id":"fh-help-center-24","index":"01","eyebrow":"Help center","title":"Find it *fast.*","lede":"Seven topics, written in plain words.","buttonLabel":"Open the help center","buttonHref":"/help","rows":[{"kind":"Start here","title":"Getting started: what Frequency is and how to find your people","meta":"","href":"/help/getting-started"},{"kind":"Groups","title":"Circles and events: how gatherings work","meta":"","href":"/help/groups"},{"kind":"Hosting","title":"Leading a Circle: start one, run the first night, keep it going","meta":"","href":"/help/leading"},{"kind":"Spaces","title":"Running a Space: the tools a Space gives you","meta":"","href":"/help/spaces"},{"kind":"The Quest","title":"Zaps, Gems, ranks and rewards","meta":"","href":"/help/the-quest"},{"kind":"Membership","title":"What''s free and what Crew adds","meta":"","href":"/help/membership"},{"kind":"Safety","title":"Reporting, blocking and how moderation works","meta":"","href":"/help/safety"}],"register":"auto"}},{"type":"NewWorldFaq","props":{"id":"fh-help-faq-25","index":"02","eyebrow":"Questions","title":"Good to *know.*","lede":"Still stuck? Open a ticket or email us.","phone":"","email":"hello@frequencylocal.com","hours":"","areasLabel":"","areas":[],"rows":[{"question":"How do I open a help ticket?","answer":"Go to Help and support, describe what happened, and send it. You can follow every reply from your tickets on the same page."},{"question":"Something feels unsafe. What do I do?","answer":"Use Report on the post, profile or event, or open a ticket marked safety. If anyone is in immediate danger, call emergency services first."},{"question":"I have a billing question.","answer":"Open a ticket and choose billing. Include the email on your account so we can find it quickly."},{"question":"How do I start a Space for my business or group?","answer":"Read Running a Space in the help center, then create one from the Spaces page. The help desk can walk you through it."},{"question":"Can I suggest a feature?","answer":"Yes, please. Post it in the community forum so others can add to it, or open a ticket if it is about your own account."}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-help-26","aside":"Generous structure. Real care. On time.","title":"Still stuck? *Ask us.*","primaryLabel":"Open a help ticket","primaryHref":"/support","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","note":"","register":"auto"}}]},"seo":{"title":"Help desk · Frequency","description":"Open a help ticket, browse the help center, or ask the community."},"comments":[]},{"slug":"about","label":"About","doc":{"root":{"props":{}},"content":[{"type":"NewWorldAboutHero","props":{"id":"fh-about-hero-27","eyebrow":"Our story · Frequency","title":"Build circles, *not walls.*","lead":"Frequency is a community collective that spreads town by town through local hosts. This Space is where the team shares the programs, the training, the answers and the conversation in the open.","chips":[{"icon":"check","text":"Free to start"},{"icon":"users","text":"Run with its members"},{"icon":"heart","text":"Care designed in"}],"primaryLabel":"Explore programs","primaryHref":"/spaces/hq/programs","secondaryLabel":"Ask the community","secondaryHref":"/spaces/hq/community","image":"/sites/new-world/photos/circle-sunrise.webp","alt":"A wide circle of people seated on a plaza at sunrise","name":"Daniel Tyack","role":"Founder","register":"auto"}},{"type":"NewWorldLongStory","props":{"id":"fh-about-roots-28","index":"01","eyebrow":"Where this comes from","title":"Old practices, *plain words.*","paragraphs":["Sitting in a circle and taking turns to speak is one of the oldest ways people have gathered. We did not invent it. We gave it a rhythm, PULSE, that a new host can learn in a week and a returning guest can trust.","Our host training draws on a few sources worth reading in full. The Way of Council, as taught by Jack Zimmerman and Virginia Coyle, gives us the talking piece and its intentions. Parker Palmer and the Center for Courage and Renewal give us touchstones for trustworthy space, like no fixing and honest, open questions. Priya Parker gives us generous authority: a host who protects, connects and equalizes the room. SAMHSA gives us the six principles of a trauma-informed approach.","Everything is written in plain words, because a host should be able to read an agreement aloud without explaining it."],"register":"auto"}},{"type":"NewWorldQuote","props":{"id":"fh-about-quote-29","label":"In Daniel’s words","quote":"The structure exists to serve the circle. The circle *governs the structure.*","by":"Daniel Tyack · Founder","register":"auto"}},{"type":"NewWorldTeam","props":{"id":"fh-about-team-2a","index":"02","eyebrow":"The team","title":"Who *runs this.*","lede":"","note":"Trained hosts join this list as they become mentors.","rows":[{"name":"Daniel Tyack","role":"Founder · The Janitor","image":"/brand/frequency/photos/daniel-tyack.jpg","alt":"Daniel Tyack smiling"}],"register":"auto"}},{"type":"NewWorldCloser","props":{"id":"fh-closer-about-2b","aside":"Generous structure. Real care. On time.","title":"Pick a door. *Come in.*","primaryLabel":"Ask the community","primaryHref":"/spaces/hq/community","secondaryLabel":"Get help","secondaryHref":"/support","note":"","register":"auto"}}]},"seo":{"title":"About · Frequency","description":"Frequency is a community collective. Build circles, not walls."},"comments":[]}]}}]},"websitePublished":true,"profileData":{"about":"This is the Frequency team''s own Space: the home base for everyone building Frequency. Find our programs, take free host training on the PULSE rhythm, learn to run your community in Creator Lab, get help from a real person, and ask the community in the forum.","kind":"business","categoryLabel":"Community collective","email":"hello@frequencylocal.com","website":"https://frequencylocal.com","socials":[{"platform":"website","url":"https://frequencylocal.com"},{"platform":"instagram","url":"https://www.instagram.com/frequencylocal"},{"platform":"tiktok","url":"https://www.tiktok.com/@frequencylocal"},{"platform":"youtube","url":"https://www.youtube.com/@frequencylocal"}],"offerings":[{"title":"The Quest","blurb":"Daily practices and Journeys you take with your Circle, across the four Pillars. Show up, earn Zaps and Gems, and climb the season."},{"title":"Circles","blurb":"Small groups of 12 to 18 people who meet at the same time in the same place, on the PULSE rhythm."},{"title":"What''s happening","blurb":"Local events from Circles and Spaces near you. RSVP, add it to your calendar, bring someone."},{"title":"Creator Lab","blurb":"Business and leadership for community creators. The Business of Community 101 is free for every Space; paid Spaces add Business Hours on Zoom."},{"title":"Host training","blurb":"Free courses on the PULSE rhythm, care and consent, and the three circle formats, then a co-host apprenticeship."},{"title":"Help desk","blurb":"Open a help ticket and a real person on the Frequency team answers."}]},"profilePublished":true}'::jsonb)
