select s.id, m.pid, 'admin', 'active' from spaces s, (values ('78d47bae-c4c8-4d1c-80a0-ac69aaf98ef8'::uuid), ('c1d40f58-318b-4c7b-a331-21788d632fc9'::uuid)) m(pid) where s.slug = 'hq'
