values ('1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'circle-formats', 'The Three Circle Formats', 'Open, Community and Focus Circles: what each one is for, what the host does, and how to choose.', 'Every Frequency circle runs on the same PULSE rhythm. What changes is the format: how much the host teaches, how big the room gets, and what brings people back. Learn all three, then pick the one that fits the people you want to gather.', '78d47bae-c4c8-4d1c-80a0-ac69aaf98ef8', (select id from spaces where slug = 'hq'), 'public', 'approved', now(), 'Hosting', 'gentle', array['hosting', 'circles', 'formats', 'host training']::text[], 10, null, '{"format":"online","schedule":"Self-paced","timezone":"America/Los_Angeles","location":null,"link":null,"notes":null,"eventId":null,"gathering":null}'::jsonb, false, 0, false, '/brand/frequency/photos/gathering-03.jpg', true)
