-- 4. The phase / module / lesson tree (parents sort before children, so one insert satisfies parent_id).
insert into journey_plan_items (id, plan_id, block_type, parent_id, title, body, sort_order, required, est_minutes) values
('d973af62-2fa3-16cc-beed-dc4a6ce5830c', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'phase', null, 'Week 1 · Why we gather', 'A gathering with a clear purpose is easier to host and easier to come back to.', 0, true, null),
('7a284d21-f590-b23b-5786-ff319bdf1c4e', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'module', 'd973af62-2fa3-16cc-beed-dc4a6ce5830c', 'Why we gather', 'A gathering with a clear purpose is easier to host and easier to come back to.', 0, true, null),
('fa688787-bc66-8dda-af67-b1cf020ff77d', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'lesson', '7a284d21-f590-b23b-5786-ff319bdf1c4e', 'Name the purpose', 'Every good gathering answers one question: what is this for? Not ''connection'' or ''community'' in general, but something specific enough that someone could disagree with it.

Try it: finish this sentence for a circle you''d like to host. "We gather so that ___." Then cut it until it fits on one line.', 0, true, 10),
('86ab3348-d4a4-b80e-ee33-b638947a6876', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'reading', '7a284d21-f590-b23b-5786-ff319bdf1c4e', 'Generous authority', 'Hosts often hold back so they don''t seem bossy. Priya Parker calls the better way generous authority: using your role to protect your guests, connect them to each other, and keep everyone roughly equal for the time you''re together.

In practice that means you set the agreements, you keep the time, and you gently step in when one voice starts to fill the room. A chill host leaves people to fend for themselves. A generous one takes care of them.', 1, true, 10),
('959b9f74-ffd0-e6f2-2073-53810f2cc2cc', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'reflection', '7a284d21-f590-b23b-5786-ff319bdf1c4e', 'Reflect: the best room you were ever in', 'Think of a gathering where you felt truly welcome. What did the host do before it started, at the door, and at the end? Write down three things you want to borrow.', 2, true, 10),
('8d8e3ab0-e601-681e-b157-44e4287633a5', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'phase', null, 'Week 2 · The PULSE rhythm', 'Five beats, the same order every time, so anyone can walk into any Frequency circle and know where they are.', 1, true, null),
('6f57780c-886e-f664-9acc-be3e4189c0a2', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'module', '8d8e3ab0-e601-681e-b157-44e4287633a5', 'The PULSE rhythm', 'Five beats, the same order every time, so anyone can walk into any Frequency circle and know where they are.', 0, true, null),
('6db57415-8491-e8bf-f808-e4c05b040969', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'lesson', '6f57780c-886e-f664-9acc-be3e4189c0a2', 'P · Presence (10 min)', 'Arrive. A few slow breaths, feet on the floor, phones away. The host sets the tone by going first.

What the host does: Start on time. Welcome people by name. Name the purpose of tonight in one sentence.', 0, true, 8),
('8852c7e0-5cd1-72fb-2b8a-b9fb7c1a2a57', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'lesson', '6f57780c-886e-f664-9acc-be3e4189c0a2', 'U · Unite (20 min)', 'A check-in round. Each person says how they''re arriving, and everyone else listens without replying.

What the host does: Read the agreements. Ask one question everyone can answer. Keep it lean so everyone gets a turn.', 1, true, 8),
('7b2227cc-dd7e-4322-cff4-b61c4f1843d1', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'lesson', '6f57780c-886e-f664-9acc-be3e4189c0a2', 'L · Lead (35 min)', 'Tonight''s practice: a teaching, a movement, a conversation or a skill. The part that changes from week to week.

What the host does: Give clear steps, an invitation and an opt-out. Watch the room more than your notes.', 2, true, 8),
('bf0bf9da-8780-222a-a166-f785efa723f1', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'lesson', '6f57780c-886e-f664-9acc-be3e4189c0a2', 'S · Settle (15 min)', 'Quiet integration. Rest, journal or sit with what came up before anyone has to talk about it.

What the host does: Lower the pace. Offer a simple prompt. Let silence do some of the work.', 3, true, 8),
('0c97424a-2abe-2196-d9f7-dcb36a1c2f48', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'lesson', '6f57780c-886e-f664-9acc-be3e4189c0a2', 'E · Exhale (10 min)', 'Close together. One word or one line each, a thank you, and a clear end.

What the host does: End on time. Say what happens next and how people can reach you.', 4, true, 8),
('b9cd891e-8111-f30b-0781-6b2d487919a0', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'exercise', '6f57780c-886e-f664-9acc-be3e4189c0a2', 'Practice: time a 90-minute night', 'Use the five beats to plan a 90-minute circle on paper: 10, 20, 35, 15 and 10 minutes. Write one line for what happens in each beat. Then cut ten minutes from Lead and see what you would keep.', 5, true, 15),
('bff1bc52-b08f-96d6-d37f-45b92712649f', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'phase', null, 'Week 3 · Setting the room', 'Most of hosting happens before anyone speaks.', 2, true, null),
('ff0a64ec-6729-9ea0-91f8-224bb8bde5b1', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'module', 'bff1bc52-b08f-96d6-d37f-45b92712649f', 'Setting the room', 'Most of hosting happens before anyone speaks.', 0, true, null),
('819541e0-83d5-3c72-64ab-2d2b6b5a5a72', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'lesson', 'ff0a64ec-6729-9ea0-91f8-224bb8bde5b1', 'Chairs in a circle', 'Set one circle with no back row, and no more seats than you expect people. Empty chairs feel like absence. Put something simple in the middle so people have a place to rest their eyes.

Check the room 20 minutes early: light, temperature, water, a sign on the door, and a place for phones.', 0, true, 8),
('b38ccd42-44a3-f8a3-5795-a5d9e1527989', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'reading', 'ff0a64ec-6729-9ea0-91f8-224bb8bde5b1', 'The talking piece', 'A talking piece is any object passed hand to hand. Whoever holds it speaks. Everyone else listens. It slows a room down and gives quiet people a real turn.

The Way of Council offers four intentions worth teaching your circle: speak from the heart, listen from the heart, speak without rehearsing, and keep it lean so everyone gets a turn.', 1, true, 8),
('b5f22157-01c9-3f43-4ba5-89eddfd0fbe0', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'lesson', 'ff0a64ec-6729-9ea0-91f8-224bb8bde5b1', 'Reading the agreements', 'Read the agreements out loud at the start of every circle, even when everyone has heard them before. It takes a minute and it''s what makes the room safe enough to be honest.

- Every practice is an invitation. Join in, go gently, watch, or pass. No one needs a reason.
- What is shared stays here. Take the lessons home. Leave the stories and the names in the room.
- Speak for yourself. Use I. Speak from your own life, not about anyone else''s.
- No fixing. Listen without advising, correcting or rescuing. Ask an honest question, or simply say thank you.
- Start and end on time. A clear start and a clear end are a kindness. People can plan around you.
- Ask before touch. No touch without a clear yes, every time. Nothing sexual happens in a circle.', 2, true, 8),
('bfe80d75-c800-5041-b08d-23ea27685613', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'phase', null, 'Week 4 · Your first circle', 'Plan it, run it, close it, follow up.', 3, true, null),
('849dcb14-0318-cd0d-df29-d481e27c4c14', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'module', 'bfe80d75-c800-5041-b08d-23ea27685613', 'Your first circle', 'Plan it, run it, close it, follow up.', 0, true, null),
('a8da8688-4fba-252d-1411-9d6fdaae5ace', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'exercise', '849dcb14-0318-cd0d-df29-d481e27c4c14', 'Write your run sheet', 'One page. The purpose in one line. The five beats with times. The check-in question. The Lead practice, with an opt-out. The closing line. Who to call if something comes up.', 0, true, 15),
('df7d4f6b-3023-d0c2-d172-2bb2c58525bb', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'lesson', '849dcb14-0318-cd0d-df29-d481e27c4c14', 'Closing on time', 'Ending well matters as much as starting well. Give a five-minute signal, close with one word each, say thank you, and say clearly when and where you''ll meet next. Then stop.', 1, true, 6),
('ffe16538-9899-b67c-6e9f-2412b3c2234a', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'lesson', '849dcb14-0318-cd0d-df29-d481e27c4c14', 'The follow-up', 'Within a day, send one short note: thank you, the next date, and one line about what you noticed. Mark attendance in Frequency so you know who came back.', 2, true, 6),
('474ba906-0bcc-9a51-4886-2cfc9c9130f5', 'b683afb5-5ff3-372d-e081-7952ea0ed28b', 'reflection', '849dcb14-0318-cd0d-df29-d481e27c4c14', 'Reflect: what will you keep?', 'After your first co-hosted circle, write three lines. What worked. What you''d change. What you need help with. Bring them to your mentor.', 3, true, 10),
('012a9ad4-5707-de52-b79a-9ce798aa2424', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'phase', null, 'Trauma-informed basics', 'What it means, and what it doesn''t.', 0, true, null),
('4e33abff-74d8-eec5-e3d9-e31ce09f6952', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'module', '012a9ad4-5707-de52-b79a-9ce798aa2424', 'Trauma-informed basics', 'What it means, and what it doesn''t.', 0, true, null),
('c58ca95e-0f1e-7caf-9833-500bce1a00b3', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'reading', '4e33abff-74d8-eec5-e3d9-e31ce09f6952', 'Not therapy, still careful', 'Trauma-informed hosting doesn''t mean diagnosing anyone or assuming everyone in the room has been through something. It means giving people clarity, choice and voice, and taking away needless sources of stress.', 0, true, 8),
('21e06a02-3904-ea7c-bbd8-cca35d7a1b18', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'lesson', '4e33abff-74d8-eec5-e3d9-e31ce09f6952', 'Safety', 'People know where they are, what will happen and how to leave. Physical and emotional safety come before the plan.', 1, true, 5),
('ffa9544e-e908-980f-2078-1df2bfc498bc', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'lesson', '4e33abff-74d8-eec5-e3d9-e31ce09f6952', 'Trust and transparency', 'Say what is coming before it comes. No surprises, no hidden agendas, no trick exercises.', 2, true, 5),
('e3c6dd59-424c-ed1b-f423-e60a72c481bf', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'lesson', '4e33abff-74d8-eec5-e3d9-e31ce09f6952', 'Peer support', 'A circle isn''t therapy. People support each other as equals, with the host as a guide, not a fixer.', 3, true, 5),
('8d610d17-b6da-cd16-e8df-6ad146c67e42', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'lesson', '4e33abff-74d8-eec5-e3d9-e31ce09f6952', 'Collaboration', 'Make agreements with the group, not at them. Share power where you can.', 4, true, 5),
('9534184a-de30-1bca-eb08-50b0fbf4fcb9', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'lesson', '4e33abff-74d8-eec5-e3d9-e31ce09f6952', 'Choice and voice', 'Every practice has an opt-out. Silence is a valid answer. Passing is always allowed.', 5, true, 5),
('68d27418-4f07-0e0b-172b-14e7c8d4fe50', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'lesson', '4e33abff-74d8-eec5-e3d9-e31ce09f6952', 'Culture and context', 'People arrive with different histories. Notice who is missing, who is quiet and who is carrying more.', 6, true, 5),
('255de6bf-e681-ab06-6ab7-0968d0217fb6', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'phase', null, 'Agreements and consent', 'The few lines that make honesty possible.', 1, true, null),
('eb9cdf4a-2e61-d3b6-e9fb-38ed4f7e7322', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'module', '255de6bf-e681-ab06-6ab7-0968d0217fb6', 'Agreements and consent', 'The few lines that make honesty possible.', 0, true, null),
('e976cea6-e5f4-18bf-5426-11c7a4421d5e', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'lesson', 'eb9cdf4a-2e61-d3b6-e9fb-38ed4f7e7322', 'The six agreements', '- Every practice is an invitation. Join in, go gently, watch, or pass. No one needs a reason.
- What is shared stays here. Take the lessons home. Leave the stories and the names in the room.
- Speak for yourself. Use I. Speak from your own life, not about anyone else''s.
- No fixing. Listen without advising, correcting or rescuing. Ask an honest question, or simply say thank you.
- Start and end on time. A clear start and a clear end are a kindness. People can plan around you.
- Ask before touch. No touch without a clear yes, every time. Nothing sexual happens in a circle.', 0, true, 8),
('44f4df39-e0b3-9a73-95f9-fbb320b139ba', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'lesson', 'eb9cdf4a-2e61-d3b6-e9fb-38ed4f7e7322', 'Invitation, never instruction', 'Phrase every practice as an invitation with a way out: "If you''d like to, close your eyes. Eyes open is fine too." Offer three ways in: join, go gently, or watch. Then mean it. Never single out the person who passes.', 1, true, 8),
('e61eb327-4a66-1917-fb44-f6a75fc463b6', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'lesson', 'eb9cdf4a-2e61-d3b6-e9fb-38ed4f7e7322', 'Touch and closeness', 'Ask before any touch, every time, and accept no as easily as yes. Offer a no-touch version of every partner practice. Nothing sexual happens in a Frequency circle, and that''s said out loud.', 2, true, 6),
('b7574bf2-bc91-c510-8887-58987235e3f0', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'phase', null, 'When something comes up', 'Tears, disclosures, a dominant voice, a room that goes cold.', 2, true, null),
('04f80648-550f-a685-cd30-8572b4c8ba60', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'module', 'b7574bf2-bc91-c510-8887-58987235e3f0', 'When something comes up', 'Tears, disclosures, a dominant voice, a room that goes cold.', 0, true, null),
('85087204-3fb5-6b67-7ba7-88918fada1e5', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'lesson', '04f80648-550f-a685-cd30-8572b4c8ba60', 'Strong feelings in the room', 'Tears aren''t an emergency. Slow down, let the person finish, thank them, and offer a breath for the whole circle. Don''t rush to fix or move on. If someone seems overwhelmed, offer a simple choice: stay, step out with a co-host, or take a pause.', 0, true, 8),
('efdd7b79-9b78-f5b0-748c-f9922ba5cb71', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'lesson', '04f80648-550f-a685-cd30-8572b4c8ba60', 'A disclosure', 'If someone shares something that suggests they''re at risk or someone else is, thank them, don''t press for details in the circle, and speak with them privately afterwards. Know your local crisis line and share it. In the US, call or text 988. If anyone is in immediate danger, call emergency services.', 1, true, 10),
('bd7877a1-1fdd-03ae-e585-8b46e1163c26', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'lesson', '04f80648-550f-a685-cd30-8572b4c8ba60', 'One voice filling the room', 'Protect the circle with warmth: "Thank you. Let''s hear from someone who hasn''t spoken yet." Use the talking piece. Set a time per share before the round starts, not after it runs long.', 2, true, 8),
('e5ae9828-3876-daba-6c4b-2c794d825989', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'exercise', '04f80648-550f-a685-cd30-8572b4c8ba60', 'Your referral route', 'Write it down before you host: the local crisis line, two counselors or clinics you can name, and the Frequency contact you call after a hard night. Keep it on your run sheet.', 3, true, 10),
('6e0c71ea-2164-1c65-f6f3-0f40823f53da', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'phase', null, 'Caring for the host', 'You can''t keep a room you''re too depleted to sit in.', 3, true, null),
('ab71f71e-c08c-f42b-e883-ebb7efad519c', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'module', '6e0c71ea-2164-1c65-f6f3-0f40823f53da', 'Caring for the host', 'You can''t keep a room you''re too depleted to sit in.', 0, true, null),
('ece22935-ce4e-0b82-c8e5-855c2ee1bf72', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'lesson', 'ab71f71e-c08c-f42b-e883-ebb7efad519c', 'After a hard night', 'Debrief with your co-host or mentor within a day. Say what happened, what you did, and what you''re still carrying. Hosting is a team practice, not a solo act.', 0, true, 6),
('e0e28c5f-5ae6-7042-ed7d-fcfd9f47b8ec', '3bcd3261-293f-ae45-a34e-ce51c49234e4', 'reflection', 'ab71f71e-c08c-f42b-e883-ebb7efad519c', 'Reflect: your limits', 'What kinds of shares are hardest for you to hear? What will you do in the moment, and who will you call afterwards?', 1, true, 10),
('984c531d-efcc-ef03-c9f8-748295e10dc9', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'phase', null, 'Open Circle', '12 to 18 people · 60 to 90 min', 0, true, null),
('2d5c5522-00fa-cdb9-3cb7-363f35bc74c9', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'module', '984c531d-efcc-ef03-c9f8-748295e10dc9', 'Open Circle', '12 to 18 people · 60 to 90 min', 0, true, null),
('2fe8082e-e911-cfd1-e69f-1ff8012257d1', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'lesson', '2d5c5522-00fa-cdb9-3cb7-363f35bc74c9', 'Open Circle: what it is', 'The host keeps the room, with no teaching agenda. People come to be heard and to hear each other.', 0, true, 6),
('e0f4ff78-0f06-f05d-8d6f-058a1118b957', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'lesson', '2d5c5522-00fa-cdb9-3cb7-363f35bc74c9', 'What the host does', 'You open and close, keep the agreements and the time, and pass the turn. You speak least.', 1, true, 6),
('1513c957-de52-1430-4bfa-bc20a5be0eb6', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'lesson', '2d5c5522-00fa-cdb9-3cb7-363f35bc74c9', 'When to choose it', 'A first circle in a new town. A standing weekly night. Anyone can walk in.', 2, true, 5),
('cce9fd64-06fc-df6b-70b2-f2e1a0154b36', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'phase', null, 'Community Circle', '12 to 18 people · 90 min', 1, true, null),
('18931e29-5681-62dd-dfb4-ccc01308518f', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'module', 'cce9fd64-06fc-df6b-70b2-f2e1a0154b36', 'Community Circle', '12 to 18 people · 90 min', 0, true, null),
('8d91f889-7144-0d63-72b9-20665151ebe1', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'lesson', '18931e29-5681-62dd-dfb4-ccc01308518f', 'Community Circle: what it is', 'A hosted circle around one shared theme: moon circles, men''s and women''s circles, grief, new parents, sharing circles.', 0, true, 6),
('15e86717-d8b4-830d-40b5-3c1c44fbbd7e', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'lesson', '18931e29-5681-62dd-dfb4-ccc01308518f', 'What the host does', 'You choose the theme and the question for the round, and keep the circle on it.', 1, true, 6),
('2b510b58-9f75-98ac-b48f-1472ff0aeedb', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'lesson', '18931e29-5681-62dd-dfb4-ccc01308518f', 'When to choose it', 'People who share a season of life. A recurring date that builds the same faces over time.', 2, true, 5),
('61e86a3a-9cc7-69e6-66bf-7c84a2ba7896', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'phase', null, 'Focus Circle', 'Up to 50 people · 90 to 120 min', 2, true, null),
('f8c58274-bdb5-1bfe-aba9-4741afbec7cf', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'module', '61e86a3a-9cc7-69e6-66bf-7c84a2ba7896', 'Focus Circle', 'Up to 50 people · 90 to 120 min', 0, true, null),
('ef8436ea-d5c8-f754-6908-2e24e3312720', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'lesson', 'f8c58274-bdb5-1bfe-aba9-4741afbec7cf', 'Focus Circle: what it is', 'The host teaches a modality: breathwork, sound, movement, a skill. The PULSE rhythm wraps the teaching so the room still feels like a circle.', 0, true, 6),
('102f864e-5e29-499c-51f7-829d1c255e51', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'lesson', 'f8c58274-bdb5-1bfe-aba9-4741afbec7cf', 'What the host does', 'You teach in the Lead beat, and the four beats around it keep it personal and safe.', 1, true, 6),
('79a1d674-0b10-06d6-d466-3d642c608712', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'lesson', 'f8c58274-bdb5-1bfe-aba9-4741afbec7cf', 'When to choose it', 'Practitioners sharing their work. A doorway into a Space''s longer programs.', 2, true, 5),
('fc90c341-b82b-4cd7-e710-4dfdc16ebfdc', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'phase', null, 'Choosing your format', 'Start where the people are.', 3, true, null),
('14526af9-b9d7-1002-0769-f05500606b6f', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'module', 'fc90c341-b82b-4cd7-e710-4dfdc16ebfdc', 'Choosing your format', 'Start where the people are.', 0, true, null),
('7ad59a30-cbd9-bb8e-edc5-b266e8edb879', '1fa3f64b-a07e-9ee6-671f-6bcaab9093bf', 'exercise', '14526af9-b9d7-1002-0769-f05500606b6f', 'Pick one and start', 'Write down who you want in the room and why they would come back. If they mainly need to be heard, start an Open Circle. If they share a season of life, a Community Circle. If you have a practice to teach, a Focus Circle. Set a date before you feel ready.', 0, true, 10),
('fdf8b38e-3ac2-0d3d-dfdd-c901aab80968', '19a74831-bf25-9b34-0adc-f2c1838ce635', 'phase', null, 'Shadow', 'Watch a trained host run a full circle.', 0, true, null),
('27171cac-7f4b-3935-5c3d-0c0067e6c047', '19a74831-bf25-9b34-0adc-f2c1838ce635', 'module', 'fdf8b38e-3ac2-0d3d-dfdd-c901aab80968', 'Shadow', 'Watch a trained host run a full circle.', 0, true, null),
('e4e656ea-2a31-7f1c-70c1-8a0fec76babb', '19a74831-bf25-9b34-0adc-f2c1838ce635', 'exercise', '27171cac-7f4b-3935-5c3d-0c0067e6c047', 'Watch for the beats', 'Sit in as a participant. Afterwards, write down when each PULSE beat started and one thing the host did to make it work.', 0, true, 10),
('f26220fd-04e6-63fe-440b-03c06340c288', '19a74831-bf25-9b34-0adc-f2c1838ce635', 'lesson', '27171cac-7f4b-3935-5c3d-0c0067e6c047', 'Debrief with your mentor', 'Ask your mentor what they were paying attention to that you could not see from your seat.', 1, true, 15),
('48068ca0-947e-ef4b-3d69-0e7e53d500bc', '19a74831-bf25-9b34-0adc-f2c1838ce635', 'phase', null, 'Co-lead', 'Lead one beat, then two.', 1, true, null),
('aed91178-4dbd-24ec-3477-a7f48cba5874', '19a74831-bf25-9b34-0adc-f2c1838ce635', 'module', '48068ca0-947e-ef4b-3d69-0e7e53d500bc', 'Co-lead', 'Lead one beat, then two.', 0, true, null),
('62bcb34f-a6ed-b4fa-3bbd-e4761cee3070', '19a74831-bf25-9b34-0adc-f2c1838ce635', 'exercise', 'aed91178-4dbd-24ec-3477-a7f48cba5874', 'Lead Presence and Exhale', 'In your second circle, open and close the night. Your mentor runs the middle.', 0, true, 10),
('0d6c4263-812e-c057-5910-0b519cfeb9f5', '19a74831-bf25-9b34-0adc-f2c1838ce635', 'exercise', 'aed91178-4dbd-24ec-3477-a7f48cba5874', 'Lead Unite and Lead', 'In your third circle, run the check-in round and the practice. Your mentor opens, settles and closes.', 1, true, 10),
('4f467a87-075d-34ad-66e6-a98337e74b06', '19a74831-bf25-9b34-0adc-f2c1838ce635', 'phase', null, 'Host with a mentor', 'Your circle, your run sheet, your mentor on call.', 2, true, null),
('d5a7b31a-73aa-fd17-4013-f19b6aea0a44', '19a74831-bf25-9b34-0adc-f2c1838ce635', 'module', '4f467a87-075d-34ad-66e6-a98337e74b06', 'Host with a mentor', 'Your circle, your run sheet, your mentor on call.', 0, true, null),
('1f24d44d-b1f4-1225-711c-f2a2f80bb13b', '19a74831-bf25-9b34-0adc-f2c1838ce635', 'exercise', 'd5a7b31a-73aa-fd17-4013-f19b6aea0a44', 'Your first full circle', 'Host the whole night from your run sheet. Your mentor is reachable by phone and checks in the next day.', 0, true, 15),
('bd8be03b-869f-b169-596d-a326cbb22b73', '19a74831-bf25-9b34-0adc-f2c1838ce635', 'reflection', 'd5a7b31a-73aa-fd17-4013-f19b6aea0a44', 'Reflect and sign off', 'Write what worked, what you would change and what you still want help with. Your mentor marks you ready to host on your own.', 1, true, 10),
('91ddae9b-ef70-27cd-6bf8-eaada62383e1', '19a74831-bf25-9b34-0adc-f2c1838ce635', 'phase', null, 'Keep growing', 'Hosting gets easier with company.', 3, true, null),
('506f233a-43fd-2fa5-ac3e-2db49c18ac5a', '19a74831-bf25-9b34-0adc-f2c1838ce635', 'module', '91ddae9b-ef70-27cd-6bf8-eaada62383e1', 'Keep growing', 'Hosting gets easier with company.', 0, true, null),
('53de8ed0-980d-4e72-27be-09687ce73b3a', '19a74831-bf25-9b34-0adc-f2c1838ce635', 'lesson', '506f233a-43fd-2fa5-ac3e-2db49c18ac5a', 'Join the monthly Host Circle', 'Hosts meet once a month to practice, swap run sheets and talk through hard nights. Bring a question.', 0, true, 5),
('da5344be-8267-4aba-740b-a4dec2a54313', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'phase', null, 'Week 1 · The Engine', 'The one idea: Structure isn''t the opposite of soul. It''s what keeps the soul from burning out.

The one question: What am I willing to carry, every month, for a year?', 0, true, null),
('eb689694-17bb-c3c2-eaee-7e03ffd5d34f', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'module', 'da5344be-8267-4aba-740b-a4dec2a54313', 'The Engine', 'The one idea: Structure isn''t the opposite of soul. It''s what keeps the soul from burning out.

The one question: What am I willing to carry, every month, for a year?', 0, true, null),
('c0d2ee0c-f4f1-de1d-e0d2-8f89d24b58a4', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'reading', 'eb689694-17bb-c3c2-eaee-7e03ffd5d34f', 'The idea: slow is smooth', 'Every week runs the same way: an idea, four tools, a practice out loud, a build on Frequency, and one commitment. About an hour. Find someone to tell your commitments to. That''s most of the magic.

Now the story. Six weeks and a room. You also have the whole vision: weekly gatherings, a membership, workshops, a retreat by summer. Launching it all at once feels like momentum.

Stop. Launch the whole vision, or one small thing you can repeat? Write your answer before you read on.

Rushing doesn''t remove steps. It moves them later, where they cost more. The agreement you didn''t write and the price you didn''t work out show up in month three, in front of people. One small thing you can repeat gets the steps done while they''re cheap.

There''s a phrase for this, from Navy SEAL training: slow is smooth, smooth is fast.', 0, true, 6),
('e71080d0-b408-747d-16e1-19b175f0c396', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'lesson', 'eb689694-17bb-c3c2-eaee-7e03ffd5d34f', 'The tools: charter, board, horizon, season', 'The Charter. One page: a purpose someone could disagree with, who it''s for, the one offering, and what you won''t do. That last line is what lets you say no to good ideas that aren''t yours to carry.

The Board. Every open piece of work somewhere you can see it. Three things active at once, no more. Sticky notes, a spreadsheet or an app: visible and capped is what matters.

The Horizon. Fourteen days. If it isn''t happening in the next two weeks, it goes to the parking lot. One weekly review, same time every week, keeps it honest.

The Season. Thirteen weeks, three priorities, and one cool-down week on the calendar before it starts. Rest is scheduled, not earned. The person who burns out takes the whole gift with them.', 1, true, 10),
('d42a67c0-9861-d04f-d610-81695dcf8a42', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'exercise', 'eb689694-17bb-c3c2-eaee-7e03ffd5d34f', 'Practice: say what you carry', 'Stand up and say every open loop out loud. The unanswered email, the half-promised event, the money thing you''re avoiding. Say it to a friend who just listens, or record it on your phone.

Then sort it. Three go on the board. Everything else goes to the parking lot: written down, not forgotten, not active.

Notice what it''s like to carry three things instead of everything.', 2, true, 10),
('cca7a2c3-779f-8548-7580-59ee190c70b7', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'exercise', 'eb689694-17bb-c3c2-eaee-7e03ffd5d34f', 'Build it on Frequency', 'The same practice, done inside your own Space.

- Create your Space from Start a Space
- Pick a starter preset in Manage, Mode. It only seeds a layout and wording; every tool stays on
- Publish your first Event from New event
- Open your Space calendar and see it there

You leave with: a live Space and one Event. No Space yet? Do it on paper. It still counts as practice.', 3, true, 15),
('27f8aadb-8f47-37c7-71a8-6054665754c2', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'reflection', 'eb689694-17bb-c3c2-eaee-7e03ffd5d34f', 'Commit, and fill in your sheet', 'Write the whole sentence: "When [weekly review time] arrives, I will open the board and empty my head, even if nothing is due." Name the time and the place. "Sunday evening" is a wish. "Sunday at 7pm at the kitchen table" is a plan.

Write it down. Then say it out loud to one person: a friend, your accountability partner, anyone who''ll remember. A plan you''ve only thought about is easy to drop. One you''ve said to someone is harder to.

Your one-page sheet:

- Purpose (could someone disagree?):
- Who it''s for:
- The one offering:
- What we won''t do:
- Active (three max):
- Weekly review time:
- This season: three priorities and one cool-down week

Before next week: run one weekly review at the time you picked.', 4, true, 10),
('138db807-1c13-9327-6e13-d1c4bdcf146d', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'phase', null, 'Week 2 · The Container', 'The one idea: A container isn''t what you believe. It''s what you''ve written down, said out loud, and will enforce.

The one question: Who is this space for, and what am I protecting?', 1, true, null),
('b96f8d4d-f7e4-58f3-ad06-a0105f067599', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'module', '138db807-1c13-9327-6e13-d1c4bdcf146d', 'The Container', 'The one idea: A container isn''t what you believe. It''s what you''ve written down, said out loud, and will enforce.

The one question: Who is this space for, and what am I protecting?', 0, true, null),
('157c3610-99d2-06d0-3f00-e4f07846d4ea', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'reading', 'b96f8d4d-f7e4-58f3-ad06-a0105f067599', 'The idea: test before the title', 'Every room has a container, whether you built it or not. If you didn''t, the habits of whoever is there build it for you.

Daniel tells this week''s story live in the workshop, and it lands here after the pilot. The point of it: character shows in what someone does when nobody is watching, and the test comes before the title.

Until then, use your own. Write a few honest sentences on one of these, and stop at the moment of decision:

- A role you gave someone and regretted. What was the first sign?
- A boundary you didn''t set. What was the night you paid for it?

Then count the rules your gatherings run on that you''ve actually written down, said out loud, and would enforce. Keep the number.', 0, true, 6),
('180d68c9-e3cb-62db-8e77-c3d6d7f397a9', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'lesson', 'b96f8d4d-f7e4-58f3-ad06-a0105f067599', 'The tools: agreements, ladder, decisions, roles', 'Agreements. Read aloud at every opening, not just posted. Confidentiality and its limits, speak from I, the right to pass, no fixing, consent for touch, and the practical ones: phones, shoes, clean-up. Add a welcome ritual for new people.

The Ladder. Four steps, written before you need them, because you won''t be calm when you do: a private word, limited participation, time away, out. Name one person who receives concerns, and when the concern is about you, it can''t be you.

Decisions. Anything that affects the group goes by consent: ask "any strong objection?", not "does everyone agree?" Everything else goes by advice: you decide after asking the people it affects.

Roles. No title before unglamorous work. The people who should lead are the ones who come early to set up the room and stay to pick up the trash. Give roles a term, and keep one helper for every ten people.', 1, true, 10),
('c5c68b76-9484-3134-2123-c7fc41792a8d', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'exercise', 'b96f8d4d-f7e4-58f3-ad06-a0105f067599', 'Practice: the no', 'Pick one real boundary your room needs. Say it out loud three times, to a friend or your phone''s camera, until it stops apologizing: no rising tone, no "sorry, but".

Then receive one. Have your friend say a boundary to you, and answer with two words: "Got it."', 2, true, 10),
('a92a2ba5-9e8c-5145-26fd-e1a817e4dc44', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'exercise', 'b96f8d4d-f7e4-58f3-ad06-a0105f067599', 'Build it on Frequency', 'The same practice, done inside your own Space.

- In Manage, Community wall, choose who can read the wall and who can post
- Post your agreements on the wall and pin them, so every member sees them first
- In Settings, Members, give one other person a role: Admin, Moderator or Editor
- Reports land in Community wall, where you can remove a post or ban a person. Agree who reads them

A free Space has one team seat, yours. A second team member comes with a paid Space.

You leave with: agreements live and one other person holding a role. No Space yet? Do it on paper. It still counts as practice.', 3, true, 15),
('d041ee99-f3e6-94fa-2852-9ae448e76296', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'reflection', 'b96f8d4d-f7e4-58f3-ad06-a0105f067599', 'Commit, and fill in your sheet', 'Write the whole sentence: "When someone crosses [line], I will [first step], within 24 hours." Name a line you can see. "Disrespect" is too vague. "Talks over someone who''s sharing" isn''t.

Write it down. Then say it out loud to one person: a friend, your accountability partner, anyone who''ll remember. A plan you''ve only thought about is easy to drop. One you''ve said to someone is harder to.

Your one-page sheet:

- Our agreements, as I read them aloud:
- Step 1, a private word:
- Step 2, limited participation:
- Step 3, time away:
- Step 4, out:
- Who receives concerns:
- Our welcome ritual:

Before next week: read your agreements aloud at your next gathering, all of them, before anything else starts.', 4, true, 10),
('75a5ab8a-32e1-b0f9-6bad-d65b10926f47', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'phase', null, 'Week 3 · The Gathering', 'The one idea: Whatever authority you don''t hold, the loudest guest will.

The one question: What is this gathering for, that someone could disagree with?', 2, true, null),
('c4a0abde-6636-ec9e-293c-65257afb5362', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'module', '75a5ab8a-32e1-b0f9-6bad-d65b10926f47', 'The Gathering', 'The one idea: Whatever authority you don''t hold, the loudest guest will.

The one question: What is this gathering for, that someone could disagree with?', 0, true, null),
('4c903695-7532-cb8d-d12b-eee5890e9021', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'reading', 'c4a0abde-6636-ec9e-293c-65257afb5362', 'The idea: preparation buys presence', 'Every gathering has someone in charge. If it isn''t you, it''s whoever is loudest.

Daniel tells this week''s story live in the workshop, and it lands here after the pilot. The point of it: what you prepare beforehand decides whether you''re free in the room or trapped by it.

Until then, use your own. Write a few honest sentences, and stop at the moment of decision:

- A gathering that came apart at a transition. Where were you standing?
- A night you had to choose between fixing the room and holding it.', 0, true, 6),
('421ba3bf-f855-e8e3-5548-a284a4c5719e', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'lesson', 'c4a0abde-6636-ec9e-293c-65257afb5362', 'The tools: purpose, arc, run of show, peak and close', '"A sound bath" is a category. "A place where people who can''t sleep learn one thing to do at 2am" is a purpose. Someone could disagree with it, and that''s what makes it useful. Ask who it serves, and who dilutes it.

The Arc. Arrive and engage, what came up, grounding. Coming down takes at least as long as going up. Announce the arc, name what''s optional, never touch without asking, and make leaving cost nothing.

The Run of Show. One page: clock, beat, owner. A beat with no owner is yours by default. Add three short checklists: one week out, doors, shutdown.

Peak and close. People remember the best moment and the ending, so design those two on purpose. The next morning, take fifteen minutes: what was supposed to happen, what happened, why, and what you''ll keep or change.', 1, true, 10),
('3033def4-e3cc-a3f3-e083-ff2d276237d1', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'exercise', 'c4a0abde-6636-ec9e-293c-65257afb5362', 'Practice: run the room', 'Stand up and walk your next gathering out loud, beat by beat, saying the words you''ll actually say.

Halfway through, get interrupted: a friend cuts in with a question or a late arrival, or a timer goes off. Handle it, then find your place on the run of show and carry on. That''s what the page is for.', 2, true, 10),
('bf145f8d-2db7-f2ca-aae7-3437f8895b56', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'exercise', 'c4a0abde-6636-ec9e-293c-65257afb5362', 'Build it on Frequency', 'The same practice, done inside your own Space.

- On your Event, keep it a free RSVP, or set ticket tiers. Selling tickets needs a paid Space
- Add event questions, so you know who is coming before they arrive
- Invite a co-host from the Event
- Reminders go to everyone who RSVPs on their own. Make sure the Event says what to bring
- Check people in at the door from Settings, Check-in
- Afterwards, mark who came on the Event''s manage page. Once one Event works, duplicate it for the next date

You leave with: one Event run and your first return number. No Space yet? Do it on paper. It still counts as practice.', 3, true, 15),
('0302bfa6-224c-b735-c827-0b6dbf86f68c', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'reflection', 'c4a0abde-6636-ec9e-293c-65257afb5362', 'Commit, and fill in your sheet', 'Write the whole sentence: "At my next gathering, the peak is [X] and the close is [Y]." Be concrete. "Good energy at the end" isn''t a close. "One word each, then I say the date of the next one" is.

Write it down. Then say it out loud to one person: a friend, your accountability partner, anyone who''ll remember. A plan you''ve only thought about is easy to drop. One you''ve said to someone is harder to.

Your one-page sheet:

- Purpose (could someone disagree?):
- Who it serves, who dilutes it:
- Run of show (clock, beat, owner):
- One week out / doors / shutdown:
- The peak:
- The close:

Hosting at home? Homeowners'' insurance usually excludes business activity, waivers only go so far, and selling food has its own rules. Ask your city and an insurer. This is general information, not legal or tax advice. Rules differ by place. Check with your city, your insurer and a professional before you rely on any of it.

Before next week: run one gathering off your run of show, review it the next morning, and look at who came. Next time, look at who came back.', 4, true, 10),
('42998a4e-a990-341f-8b04-620c73a0f3b2', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'phase', null, 'Week 4 · The Exchange', 'The one idea: Charging is what makes your presence renewable.

The one question: What does it cost me to keep showing up?', 3, true, null),
('2274cb70-f5db-876a-15bb-ca9707eeb341', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'module', '42998a4e-a990-341f-8b04-620c73a0f3b2', 'The Exchange', 'The one idea: Charging is what makes your presence renewable.

The one question: What does it cost me to keep showing up?', 0, true, null),
('c5fdd49b-8805-f017-7227-056af8b16c2a', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'reading', '2274cb70-f5db-876a-15bb-ca9707eeb341', 'The idea: charging keeps you here', 'A full room, people genuinely moved, and not enough in the basket to cover the night. That isn''t a generosity problem. It''s a structure problem.

Daniel tells this week''s story live in the workshop, and it lands here after the pilot. The point of it: a generous act, a number said out loud, and the cost that was paid.

Until then, write down what your last gathering cost: rent, supplies, food, gas. Then what came in. Don''t round in your favor. You''ll use both numbers in the next lesson.', 0, true, 6),
('59209d0b-a4f3-238a-d953-3cfca4f0180f', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'lesson', '2274cb70-f5db-876a-15bb-ca9707eeb341', 'The tools: break-even, ladder, base, loop', 'Break-even. Fixed costs ÷ (price − cost per head). A $425 night at $4 a head needs 14 people at $35, and 21 at $25. Ten dollars of kindness costs seven more people to find, invite and welcome, every time.

The Ladder. Three published prices: supported, sustaining, solidarity. The middle one sits at or above break-even. Cap the supported spots by number, not by asking who deserves one. A donation basket needs three things beside it: the cost per head, a suggested amount, and where any extra goes.

The Base. Memberships cover the rent; events are upside. $1,400 a month at $45 is 32 members. Keeping them is the work: get each new member to four visits in their first month.

The Loop. Guest, member, helper, leader: each step is someone carrying a bit more. Growth comes from the people already inside, so keep your list of them yourself, not on a platform that can turn down your reach.', 1, true, 10),
('d117c8ea-51bd-0854-b55a-ed36b3508827', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'exercise', '2274cb70-f5db-876a-15bb-ca9707eeb341', 'Practice: say your price', 'Say your price out loud. No "it''s only", no "but if that''s too much", no rising tone at the end.

Say it to a friend who answers with silence, and don''t fill the silence. Repeat until it lands flat, the way you''d say the time.', 2, true, 10),
('d53f6a34-4daf-e71f-f1e6-dc7ff9b93744', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'exercise', '2274cb70-f5db-876a-15bb-ca9707eeb341', 'Build it on Frequency', 'The same practice, done inside your own Space.

- In Settings, Memberships, set one membership and what it includes. A free one works on any Space
- In Settings, Donations, turn on donations and write the ask: cost per head, a suggested amount, where any extra goes
- In Settings, Shop, list one thing you already make or sell
- In your Space CRM, import your contacts, so the list is yours. People keep control of their own email settings

Taking money and the CRM need a paid Space. On a free Space, set up the free parts now.

You leave with: a published ladder, a live tier, and contacts imported. No Space yet? Do it on paper. It still counts as practice.', 3, true, 15),
('ecaa2bf0-dc84-11f1-bf84-c5f8eddf4214', '40415a8d-bb27-f3a4-37c7-c19749a349d2', 'reflection', '2274cb70-f5db-876a-15bb-ca9707eeb341', 'Commit, and finish your Community Book', 'Write the whole sentence: "My floor is $___. I won''t go below it, and I''ve told ___." Set the floor from your break-even.

Write it down. Then say it out loud to one person: a friend, your accountability partner, anyone who''ll remember. A plan you''ve only thought about is easy to drop. One you''ve said to someone is harder to.

Your one-page sheet:

- Fixed costs, cost per head, price:
- Break-even and my floor:
- Supported / sustaining / solidarity:
- Members needed to cover the month:
- How each new member gets to four visits:

Your four sheets plus a 13-week season plan are your Community Book. Finish all four weeks for Attended, 10 contact hours. Submit the Book and do the four builds in your own Space for Certified: a certificate of completion and competency, not an accredited certification. Review is free through January 31, 2027. After that it comes with a paid Space. Submissions stay open six weeks after Week 4.

Starting out on your own? Keep a separate bank account from day one, and change how you''re set up only when you need to. This is general information, not legal or tax advice. Rules differ by place. Check with your city, your insurer and a professional before you rely on any of it.

What''s next: Business Hours, the weekly room on Zoom for paid Spaces, where you bring one number and one stuck thing. And for Certified graduates, 102 when it opens.', 4, true, 15)
on conflict (id) do update set block_type = excluded.block_type, parent_id = excluded.parent_id, title = excluded.title, body = excluded.body, sort_order = excluded.sort_order, required = excluded.required, est_minutes = excluded.est_minutes;

-- 5. The house account: the primary business profile. Only display fields; never community_role or web_role
