update profiles set display_name = 'Frequency', bio = 'Gather like it matters. Frequency is a community collective: local Circles, events and the Spaces that host them. Programs, host training, Creator Lab, help and the community forum live in the Frequency Space. Need a hand? Open a help ticket and a real person answers.', website = 'https://frequencylocal.com', avatar_url = '/brand/frequency/logo/frequency-icon-round.png', header_image_url = '/brand/frequency/photos/day-meditation-circle.jpg', vcard = '{"enabled":true,"email":"hello@frequencylocal.com","phone":null,"org":"Frequency","title":"Community collective","website":"https://frequencylocal.com","includeAvatar":true}'::jsonb,
